import os
import subprocess
import fnmatch
import tarfile
import glob
from datetime import datetime

def process_files(directory_path, file_pattern, operation):
    # Validate directory path
    if not os.path.isdir(directory_path):
        return f"Error: Directory '{directory_path}' does not exist."

    try:
        # Find all files matching the pattern
        files = [os.path.join(root, f)
                 for root, _, files in os.walk(directory_path)
                 for f in files if fnmatch.fnmatch(f, file_pattern)]

        if operation == "list":
            return files
        elif operation == "count":
            return str(len(files))
        elif operation == "compress":
            if not files:
                return f"No files matched the pattern '{file_pattern}' for compression."
            archive_name = f"{file_pattern.replace('*', 'all')}_archive_{datetime.now().strftime('%Y%m%d_%H%M%S')}.tar.gz"
            archive_path = os.path.join(directory_path, archive_name)

            # Use tarfile module for compression (as subprocess can be less precise for tar.gz)
            with tarfile.open(archive_path, "w:gz") as tar:
                for file in files:
                    tar.add(file, arcname=os.path.basename(file))
            return archive_path
        else:
            return f"Error: Invalid operation '{operation}'. Choose from 'list', 'count', or 'compress'."
    except Exception as e:
        return f"Error processing files: {e}"

