import os

def read_file(base_directory, filename):
    """
    Reads the contents of a specified file within a base directory.

    Parameters:
    - base_directory (str): The base directory path.
    - filename (str): The name of the file to read.

    Returns:
    - str: The contents of the file, or an error message if the file cannot be read.
    """
    full_path = os.path.join(base_directory, filename)

    try:
        with open(full_path, 'r') as file:
            return file.read()
    except FileNotFoundError:
        return f"Error: The file '{filename}' was not found in '{base_directory}'."
    except PermissionError:
        return f"Error: Permission denied when trying to read '{filename}'."
    except Exception as e:
        return f"An unexpected error occurred: {e}"

import os

def read_file(base_directory, filename):
    """
    Reads the contents of a file from the specified base directory.

    Parameters:
    - base_directory (str): The base directory path.
    - filename (str): The name of the file to read.

    Returns:
    - str: The contents of the file if successful, or an error message if not.
    """
    full_path = os.path.join(base_directory, filename)

    try:
        with open(full_path, 'r', encoding='utf-8') as file:
            return file.read()
    except FileNotFoundError:
        return f"Error: The file '{filename}' was not found in '{base_directory}'."
    except PermissionError:
        return f"Error: Permission denied when trying to read '{filename}'."
    except Exception as e:
        return f"An unexpected error occurred: {e}"

import bcrypt

def hash_password(password: str) -> str:
    # Generate a salt and hash the password
    hashed_bytes = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())
    # Return as hexadecimal string
    return hashed_bytes.decode('utf-8')

