import requests
import json

def fetch_OSS_BSS_API_data(endpoint, api_key):
    """
    Connects to the OSS/BSS API, makes a GET request to retrieve data, and returns the response data as JSON.

    Parameters:
    endpoint (str): The OSS/BSS API endpoint URL.
    api_key (str): The OSS/BSS API key for authentication.

    Returns:
    dict: The response data from the OSS/BSS API as JSON.
    """

    # Set the API key in the headers for authentication
    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json'
    }

    try:
        # Make a GET request to the OSS/BSS API endpoint
        response = requests.get(endpoint, headers=headers)

        # Check if the request was successful
        if response.status_code == 200:
            # Return the response data as JSON
            return response.json()
        else:
            # Return an error message if the request failed
            return {'error': f'Failed to retrieve data. Status code: {response.status_code}'}
    except requests.exceptions.RequestException as e:
        # Return an error message if there was a request exception
        return {'error': f'An error occurred: {e}'}

