import requests

def fetch_https_data(url):
    """
    Fetches data from a given HTTPS URL and returns it as a JSON object.

    Parameters:
    - url (str): The HTTPS URL to fetch data from.

    Returns:
    - dict: JSON response data if successful.
    - str: Error message if an error occurs.
    """
    try:
        response = requests.get(url, timeout=10)  # 10 seconds timeout
        response.raise_for_status()  # Raise exception for 4xx, 5xx status codes
        return response.json()
    except requests.exceptions.Timeout:
        return "Error: The request timed out."
    except requests.exceptions.ConnectionError:
        return "Error: Failed to connect to the server."
    except requests.exceptions.HTTPError as http_err:
        return f"HTTP Error: {http_err}"
    except requests.exceptions.SSLError:
        return "SSL Error: Could not verify the server's SSL certificate."
    except requests.exceptions.RequestException as err:
        return f"An error occurred: {err}"

