import os
import subprocess
import tarfile

def process_plant_records(directory_path, plant_record_pattern, operation):
    """
    Processes plant records in a directory based on user input.

    Args:
        directory_path (str): The path to the directory containing the plant records.
        plant_record_pattern (str): The pattern to match plant record files (e.g., "*.log").
        operation (str): The operation to perform ("list", "count", or "compress").

    Returns:
        str or list: The result of the operation.  Returns an error message string if 
                     the operation is invalid or encounters an error.
    """

    if not os.path.isdir(directory_path):
        return f"Error: Directory '{directory_path}' does not exist."

    try:
        if operation == "list":
            try:
                result = subprocess.check_output(
                    ["find", directory_path, "-name", plant_record_pattern],
                    text=True  # Use text=True to get string output
                ).splitlines()
                return result
            except subprocess.CalledProcessError as e:
                return f"Error listing files: {e}"

        elif operation == "count":
            try:
                result = int(subprocess.check_output(
                    ["find", directory_path, "-name", plant_record_pattern, "-print0", "|", "wc", "-l"],
                    text=True,
                    shell=True # Required for piping
                ).strip())
                return str(result)
            except subprocess.CalledProcessError as e:
                return f"Error counting files: {e}"
            except ValueError:
                return "Error: Could not convert count to integer."

        elif operation == "compress":
            archive_name = os.path.join(directory_path, "plant_records.tar.gz")
            try:
                with tarfile.open(archive_name, "w:gz") as tar:
                    for root, _, files in os.walk(directory_path):
                        for file in files:
                            if file.endswith(os.path.splitext(plant_record_pattern)[1]): #Handle patterns like *.log
                                file_path = os.path.join(root, file)
                                tar.add(file_path, arcname=os.path.relpath(file_path, directory_path)) #Preserve relative path within archive

                return f"Archive created: {archive_name}"
            except Exception as e:
                return f"Error compressing files: {e}"

        else:
            return "Error: Invalid operation. Choose 'list', 'count', or 'compress'."

    except Exception as e:
        return f"An unexpected error occurred: {e}"


