import subprocess
import os

def process_recordings(directory_path, recording_pattern, operation):
    """
    Process recordings in a directory based on user input.

    Args:
        directory_path (str): The path to the directory containing recordings.
        recording_pattern (str): A pattern to match recordings (e.g., "*.log").
        operation (str): The operation to perform on the recordings ("list", "count", or "compress").

    Returns:
        str or list: The result of the operation.

    Raises:
        ValueError: If the operation is not one of "list", "count", or "compress".
    """

    # Check if the operation is valid
    if operation not in ["list", "count", "compress"]:
        raise ValueError("Invalid operation. Must be 'list', 'count', or 'compress'.")

    # Change to the directory
    try:
        os.chdir(directory_path)
    except FileNotFoundError:
        return f"Directory '{directory_path}' not found."

    # Perform the operation
    if operation == "list":
        # List all recordings matching the pattern
        result = subprocess.run(["ls", recording_pattern], capture_output=True, text=True)
        if result.returncode == 0:
            return result.stdout.splitlines()
        else:
            return f"Error listing recordings: {result.stderr.strip()}"

    elif operation == "count":
        # Count recordings matching the pattern
        result = subprocess.run(["ls", recording_pattern], capture_output=True, text=True)
        if result.returncode == 0:
            return len(result.stdout.splitlines())
        else:
            return f"Error counting recordings: {result.stderr.strip()}"

    elif operation == "compress":
        # Create a tar.gz archive of matching recordings
        archive_name = "recordings.tar.gz"
        result = subprocess.run(["tar", "-czf", archive_name, recording_pattern], capture_output=True, text=True)
        if result.returncode == 0:
            return f"Recordings compressed to '{archive_name}'"
        else:
            return f"Error compressing recordings: {result.stderr.strip()}"

