import os
import fnmatch
import subprocess
from typing import Union, List

def process_recordings(
    directory_path: str,
    recording_pattern: str,
    operation: str
) -> Union[List[str], int, str]:
    """
    Process recordings in a directory based on a file pattern and operation.

    Parameters:
        directory_path (str): Path to the directory containing recordings.
        recording_pattern (str): Pattern to match recording files (e.g., "*.log").
        operation (str): One of "list", "count", or "compress".

    Returns:
        List[str] or int or str: Result based on the operation.
    """
    # Ensure directory exists
    if not os.path.isdir(directory_path):
        raise FileNotFoundError(f"Directory not found: {directory_path}")

    # List all files matching the pattern
    matched_files = [
        os.path.join(directory_path, f)
        for f in os.listdir(directory_path)
        if fnmatch.fnmatch(f, recording_pattern)
    ]

    if not matched_files:
        return []

    if operation == "list":
        return [os.path.basename(f) for f in matched_files]
    elif operation == "count":
        return len(matched_files)
    elif operation == "compress":
        archive_name = "recordings_archive.tar.gz"
        archive_path = os.path.join(directory_path, archive_name)

        # Create tar.gz archive using subprocess
        try:
            subprocess.run(
                ["tar", "-czf", archive_path, "-T", "-"],
                input='\n'.join(matched_files).encode(),
                check=True
            )
            return archive_path
        except subprocess.CalledProcessError as e:
            return f"Compression failed: {e}"
    else:
        raise ValueError(f"Unknown operation: {operation}")

import pickle
import os

def load_config(config_recording: str) -> dict:
    """
    Loads zone configuration data from a recording.

    Args:
    - config_recording (str): Path to the zone configuration recording.

    Returns:
    - dict: Zone configuration data.

    Raises:
    - FileNotFoundError: If the config_recording file does not exist.
    """

    # Check if the file exists
    if not os.path.isfile(config_recording):
        raise FileNotFoundError(f"The configuration recording '{config_recording}' was not found.")

    try:
        # Attempt to open and deserialize the configuration recording
        with open(config_recording, 'rb') as file:
            config = pickle.load(file)
            return config
    except pickle.UnpicklingError as e:
        # Handle deserialization errors
        print(f"Failed to deserialize the configuration recording: {e}")
        return {}
    except Exception as e:
        # Handle any other unexpected errors
        print(f"An error occurred while loading the configuration: {e}")
        return {}

