import subprocess
import os
import glob
import shlex

def process_public_documents(directory_path, document_pattern, operation):
    # Validate directory path
    if not os.path.isdir(directory_path):
        return f"Error: Directory '{directory_path}' does not exist."

    # Expand the pattern to match files in the directory
    file_pattern = os.path.join(directory_path, document_pattern)
    matching_files = glob.glob(file_pattern)

    if not matching_files:
        return f"No files found matching pattern '{document_pattern}' in '{directory_path}'."

    if operation == "list":
        # List all matching files
        return matching_files

    elif operation == "count":
        # Return the count of matching files
        return str(len(matching_files))

    elif operation == "compress":
        # Create a tar.gz archive of the matching files
        archive_name = "public_documents.tar.gz"
        archive_path = os.path.join(directory_path, archive_name)

        # Build the tar command
        tar_cmd = [
            "tar",
            "-czf",  # Create a compressed tar archive
            shlex.quote(archive_path),
        ] + [shlex.quote(f) for f in matching_files]

        try:
            subprocess.run(tar_cmd, check=True)
            return f"Created archive: {archive_path}"
        except subprocess.CalledProcessError as e:
            return f"Error creating archive: {e}"

    else:
        return f"Error: Unknown operation '{operation}'. Supported operations: list, count, compress."

