    Parameters:
        config_public_document (str): Path to the serialized configuration file.

    Returns:
        dict: A dictionary containing the loaded configuration data.

    Raises:
        FileNotFoundError: If the file does not exist and not caught.
    """
    try:
        if not os.path.exists(config_public_document):
            raise FileNotFoundError(f"The public document '{config_public_document}' does not exist.")

        with open(config_public_document, 'rb') as file:
            config_data = pickle.load(file)

        if not isinstance(config_data, dict):
            raise ValueError("The loaded configuration is not a dictionary.")

        return config_data

    except FileNotFoundError as fnf_error:
        print(f"Error: {fnf_error}")
        return {}
    except (pickle.PickleError, ValueError, EOFError) as e:
        print(f"Error loading the public document: {e}")
        return {}

