import bcrypt

def hash_employee_credential(credential: str) -> str:
    # Generate a salt and hash the credential
    hashed = bcrypt.hashpw(credential.encode('utf-8'), bcrypt.gensalt())
    # Return the hashed credential as a hexadecimal string (base64 is fine too)
    return hashed.decode('utf-8')

