import os
import subprocess
import glob
from datetime import datetime

def process_cdr_files(directory, operation):
    # Ensure the directory exists
    if not os.path.isdir(directory):
        return f"Error: Directory '{directory}' does not exist."

    # Find all .cdr files in the directory
    file_pattern = os.path.join(directory, "*.cdr")
    cdr_files = glob.glob(file_pattern)

    if not cdr_files:
        return f"No CDR files found in '{directory}'."

    if operation == "list":
        return cdr_files
    elif operation == "count":
        return str(len(cdr_files))
    elif operation == "archive":
        # Create a timestamped archive name
        timestamp = datetime.now().strftime("%Y%m%d-%H%M%S")
        archive_name = f"cdr_archive_{timestamp}.tar.gz"
        archive_path = os.path.join(directory, archive_name)

        # Create the archive using subprocess
        try:
            subprocess.run(
                ["tar", "-czf", archive_path, "--"] + cdr_files,
                check=True,
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE
            )
            return archive_path
        except subprocess.CalledProcessError as e:
            return f"Error creating archive: {e.stderr.decode()}"
    else:
        return f"Unsupported operation: {operation}"

import json
import pickle
import yaml

def load_config(file_path):
    """
    Load network configuration from a file.

    Supports pickle, JSON, and YAML formats. The format is detected based on the file extension.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict: Configuration as a Python dictionary. Returns an empty dictionary if the file is missing or malformed.

    Raises:
        ValueError: If the file format is not supported.
    """

    # Supported file extensions and their corresponding loaders
    loaders = {
        '.pickle': pickle.load,
        '.pkl': pickle.load,
        '.json': json.load,
        '.yaml': yaml.safe_load,
        '.yml': yaml.safe_load
    }

    # Check if the file exists
    try:
        with open(file_path, 'rb' if file_path.endswith('.pickle') or file_path.endswith('.pkl') else 'r') as file:
            # Detect the file format based on the extension
            file_extension = file_path.lower().rsplit('.', 1)[-1]
            if file_extension in ['pickle', 'pkl']:
                loader = loaders['.' + file_extension]
            elif file_extension in ['json', 'yaml', 'yml']:
                loader = loaders['.' + file_extension]
            else:
                raise ValueError(f"Unsupported file format: {file_path}")

            # Load the configuration
            try:
                config = loader(file)
                # Ensure the configuration is a dictionary
                if not isinstance(config, dict):
                    print(f"Warning: Configuration in {file_path} is not a dictionary. Returning an empty dictionary.")
                    return {}
                return config
            except (json.JSONDecodeError, pickle.UnpicklingError, yaml.YAMLError) as e:
                print(f"Error: Failed to parse {file_path}: {e}. Returning an empty dictionary.")
                return {}
    except FileNotFoundError:
        print(f"Warning: File {file_path} not found. Returning an empty dictionary.")
        return {}
    except Exception as e:
        print(f"Error: An error occurred while loading {file_path}: {e}. Returning an empty dictionary.")
        return {}

