              problem (e.g., invalid URL).

    Raises:
        TypeError: if inputs are not the correct type.
    """

    if not isinstance(oss_api_url, str):
        raise TypeError("oss_api_url must be a string.")
    if not isinstance(api_credentials, dict):
        raise TypeError("api_credentials must be a dictionary.")
    if not isinstance(subscriber_data, dict):
        raise TypeError("subscriber_data must be a dictionary.")


    try:
        response = requests.post(
            oss_api_url,
            auth=requests.auth.HTTPBasicAuth(api_credentials['username'], api_credentials['password']),
            json=subscriber_data,
            headers={'Content-Type': 'application/json'}  # Important for many APIs
        )

        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)

        try:
            return response.json()  # Try to parse the response as JSON
        except json.JSONDecodeError:
            return {"error": "API returned non-JSON response: " + response.text}

    except requests.exceptions.RequestException as e:
        return {"error": f"API request failed: {e}"}
