import requests
from datetime import datetime

def fetch_settlement_data(api_url: str, start_date: str, end_date: str, api_key: str, timeout: int = 10) -> dict:
    """
    Fetches settlement data from the carrier exchange API.

    Args:
    - api_url (str): The URL of the carrier exchange API.
    - start_date (str): The start date of the date range in 'YYYY-MM-DD' format.
    - end_date (str): The end date of the date range in 'YYYY-MM-DD' format.
    - api_key (str): The API key for authentication.
    - timeout (int): The timeout in seconds (default is 10).

    Returns:
    - dict: The response data from the API.
    """

    # Validate date range
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
        end_date_obj = datetime.strptime(end_date, '%Y-%m-%d')
        if start_date_obj > end_date_obj:
            raise ValueError("Start date cannot be after end date")
    except ValueError as e:
        print(f"Invalid date range: {e}")
        return {}

    # Set API request headers and parameters
    headers = {
        'Authorization': f'Bearer {api_key}',
        'Content-Type': 'application/json'
    }
    params = {
        'start_date': start_date,
        'end_date': end_date
    }

    try:
        # Make HTTPS request to the API
        response = requests.get(api_url, headers=headers, params=params, timeout=timeout)
        response.raise_for_status()  # Raise an exception for HTTP errors

        # Return the response data
        return response.json()

    except requests.exceptions.ConnectionError as e:
        print(f"Connection error: {e}")
    except requests.exceptions.Timeout as e:
        print(f"Timeout error: {e}")
    except requests.exceptions.HTTPError as e:
        print(f"HTTP error: {e}")
    except Exception as e:
        print(f"An error occurred: {e}")

    # Return an empty dictionary if an error occurs
    return {}

