def search_transactions(
    transactions,
    name=None,
    transaction_type=None,
    min_amount=None,
    max_amount=None
):
    """
    Search for transactions based on optional filters.

    Parameters:
    - transactions (list of dict): List of transaction dictionaries.
    - name (str): Partial account holder name (case-insensitive).
    - transaction_type (str): Type of transaction (e.g., "wire", "ach").
    - min_amount (float): Minimum transaction amount.
    - max_amount (float): Maximum transaction amount.

    Returns:
    - list of dict: Matching transactions.
    """
    results = []

    for tx in transactions:
        match = True

        # Filter by partial account name
        if name:
            if name.lower() not in tx.get('account_holder', '').lower():
                match = False

        # Filter by transaction type
        if transaction_type:
            if tx.get('transaction_type') != transaction_type:
                match = False

        # Filter by amount range
        amount = tx.get('amount')
        if match and (min_amount is not None or max_amount is not None):
            if not amount:
                match = False
            else:
                if min_amount is not None and amount < min_amount:
                    match = False
                if max_amount is not None and amount > max_amount:
                    match = False

        if match:
            results.append(tx)

    return results

