import pickle
import yaml

def load_account_config(file_path):
    """
    Load account configuration from a file.

    Args:
    - file_path (str): Path to the configuration file.

    Returns:
    - dict or None: Configuration as a Python dictionary, or None if the file is missing or malformed.

    Raises:
    - ValueError: If the file format is not supported.
    """

    # Check if the file exists
    try:
        with open(file_path, 'rb') as file:
            # Detect file format based on extension
            if file_path.endswith('.pickle') or file_path.endswith('.pkl'):
                try:
                    return pickle.load(file)
                except pickle.UnpicklingError as e:
                    print(f"Error loading pickle file: {e}")
                    return None
            elif file_path.endswith('.json'):
                file.seek(0)  # Reset file pointer
                try:
                    return json.load(file)
                except json.JSONDecodeError as e:
                    print(f"Error loading JSON file: {e}")
                    return None
            elif file_path.endswith('.yaml') or file_path.endswith('.yml'):
                file.seek(0)  # Reset file pointer
                try:
                    return yaml.safe_load(file)
                except yaml.YAMLError as e:
                    print(f"Error loading YAML file: {e}")
                    return None
            else:
                raise ValueError(f"Unsupported file format: {file_path}")
    except FileNotFoundError:
        print(f"File not found: {file_path}")
        return None

