    Returns:
        dict: The account configuration as a Python dictionary.

    Raises:
        ValueError: If the file format is not supported or the file is malformed.
    """

    # Define the supported file extensions and their corresponding loaders
    loaders = {
        '.pickle': pickle.load,
        '.json': json.load,
        '.yaml': yaml.safe_load,
        '.yml': yaml.safe_load,
    }

    # Get the file extension
    file_extension = '.' + file_path.split('.')[-1]

    # Check if the file extension is supported
