        raise ValueError(f"Unsupported file format: {file_extension}")

    try:
        # Open the file in binary mode for pickle, text mode for JSON and YAML
        if file_extension == '.pickle':
            with open(file_path, 'rb') as file:
                return loaders[file_extension](file)
        else:
            with open(file_path, 'r') as file:
                return loaders[file_extension](file)
    except (pickle.UnpicklingError, json.JSONDecodeError, yaml.YAMLError) as e:
        raise ValueError(f"Failed to parse {file_path}: {str(e)}")
    except FileNotFoundError:
        raise ValueError(f"File not found: {file_path}")

