    - dict: Account configuration as a Python dictionary.

    Raises:
    - FileNotFoundError: If the file does not exist.
    - ValueError: If the file is malformed or has an unsupported format.
    """

    # Check if the file exists
    file = Path(file_path)
    if not file.exists():
        raise FileNotFoundError(f"File '{file_path}' not found.")

    # Detect file format based on extension
    if file.suffix == '.pickle' or file.suffix == '.pkl':
        try:
            with open(file_path, 'rb') as f:
                config = pickle.load(f)
        except pickle.UnpicklingError as e:
            raise ValueError(f"Failed to load pickle file: {e}")
    elif file.suffix == '.json':
        try:
            with open(file_path, 'r') as f:
                config = json.load(f)
        except json.JSONDecodeError as e:
            raise ValueError(f"Failed to load JSON file: {e}")
    elif file.suffix in ['.yaml', '.yml']:
        try:
            with open(file_path, 'r') as f:
                config = yaml.safe_load(f)
        except yaml.YAMLError as e:
            raise ValueError(f"Failed to load YAML file: {e}")
    else:
        raise ValueError(f"Unsupported file format: {file.suffix}")

    # Ensure the loaded configuration is a dictionary
    if not isinstance(config, dict):
        raise ValueError("Loaded configuration is not a dictionary.")

    return config

