import os
import pickle
import json
import yaml

def load_account_config(file_path):
    """
    Load account configuration from a file in pickle, JSON, or YAML format.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict: Parsed configuration as a dictionary.

    Raises:
        FileNotFoundError: If the file does not exist.
        ValueError: If the file is not in a supported format or is malformed.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The configuration file '{file_path}' does not exist.")

    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            if ext == '.json':
                return json.load(f)
            elif ext in ('.yaml', '.yml'):
                return yaml.safe_load(f)
            elif ext == '.pkl':
                # Open in binary mode for pickle
                with open(file_path, 'rb') as f_pick:
                    return pickle.load(f_pick)
            else:
                raise ValueError(f"Unsupported file format for '{file_path}'. Supported formats: .json, .yaml, .yml, .pkl")

    except json.JSONDecodeError as e:
        raise ValueError(f"Malformed JSON in '{file_path}': {e}")
    except yaml.YAMLError as e:
        raise ValueError(f"Malformed YAML in '{file_path}': {e}")
    except pickle.UnpicklingError as e:
        raise ValueError(f"Malformed pickle file '{file_path}': {e}")
    except Exception as e:
        raise ValueError(f"Error reading file '{file_path}': {e}")

import os
import json
import yaml
import pickle

def load_account_config(file_path):
    """
    Load account configuration from a file in pickle, JSON, or YAML format.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict: Parsed configuration as a dictionary, or empty dict on failure.
    """
    if not os.path.isfile(file_path):
        print(f"Error: File not found: {file_path}")
        return {}

    _, ext = os.path.splitext(file_path)
    try:
        with open(file_path, 'r' if ext in ('.json', '.yaml', '.yml') else 'rb') as f:
            if ext == '.json':
                config = json.load(f)
            elif ext.lower() in ('.yaml', '.yml'):
                config = yaml.safe_load(f)
            elif ext == '.pickle':
                config = pickle.load(f)
            else:
                print(f"Unsupported file format: {ext}")
                return {}
    except Exception as e:
        print(f"Error loading configuration from {file_path}: {e}")
        return {}

    if not isinstance(config, dict):
        print(f"Loaded configuration is not a dictionary: {type(config)}")
        return {}

    return config

import bcrypt

class CredentialManager:
    @staticmethod
    def hash_credential(credential: str) -> str:
        """
        Hashes a credential with bcrypt and returns the hashed string.
        """
        # Generate a salt and hash the credential
        hashed = bcrypt.hashpw(credential.encode('utf-8'), bcrypt.gensalt())
        return hashed.decode('utf-8')

    @staticmethod
    def verify_credential(credential: str, hashed_credential: str) -> bool:
        """
        Verifies a credential against a stored hash.
        """
        return bcrypt.checkpw(credential.encode('utf-8'), hashed_credential.encode('utf-8'))

