import requests
import json

def process_payment(amount, currency, card_number, expiry_date, cvv, customer_email):
    """
    Submits a payment transaction to a payment processor API.

    Parameters:
    - amount (float): The transaction amount
    - currency (str): The currency code (e.g., USD, EUR)
    - card_number (str): Card number
    - expiry_date (str): Expiry date in MMYY format
    - cvv (str): CVV code
    - customer_email (str): Customer's email address

    Returns:
    - dict: JSON response from the payment processor
    """

    # Replace with your payment processor's actual endpoint
    payment_api_url = "https://api.paymentprocessor.com/v1/payments"

    # Replace with your actual API key and secret
    api_key = "your_api_key"
    api_secret = "your_api_secret"

    # Payload for the payment request
    payload = {
        "amount": amount,
        "currency": currency,
        "card": {
            "number": card_number,
            "expiry": expiry_date,
            "cvv": cvv
        },
        "customer": {
            "email": customer_email
        }
    }

    # Headers for the request
    headers = {
        "Content-Type": "application/json",
        "Authorization": f"Basic {api_key}:{api_secret}"
    }

    try:
        # Make the request to the payment processor API
        response = requests.post(payment_api_url, headers=headers, data=json.dumps(payload))
        response.raise_for_status()  # Raise an error for bad status codes

        # Return JSON response from the processor
        return response.json()

    except requests.exceptions.HTTPError as err:
        return {"error": "HTTP error occurred", "details": str(err)}
    except Exception as err:
        return {"error": "Payment processing failed", "details": str(err)}

import requests
from datetime import datetime

def fetch_settlement_data(base_url, access_token, start_date, end_date, timeout=10):
    """
    Fetches settlement data from the interbank API for a given date range.

    Parameters:
        - base_url (str): The base URL of the interbank API endpoint (e.g., 'https://api.interbank.com/settlement')
        - access_token (str): Authorization token for API access
        - start_date (str): Start date in 'YYYY-MM-DD' format
        - end_date (str): End date in 'YYYY-MM-DD' format
        - timeout (int): Request timeout in seconds (default: 10)

    Returns:
        - dict: JSON response from the API if successful
        - dict: Error message if failure

    Raises:
        - requests.exceptions.RequestException: For network or timeout errors
    """

    headers = {
        'Authorization': f'Bearer {access_token}',
        'Content-Type': 'application/json'
    }

    payload = {
        'start_date': start_date,
        'end_date': end_date
    }

    try:
        response = requests.post(
            base_url,
            headers=headers,
            json=payload,
            timeout=timeout
        )

        # Raise exception for HTTP error responses (4xx, 5xx)
        response.raise_for_status()

        return response.json()

    except requests.exceptions.ConnectionError as ce:
        print(f"[ERROR] Connection error: {ce}")
        return {"error": "Unable to connect to the interbank API", "details": str(ce)}
    except requests.exceptions.Timeout as te:
        print(f"[ERROR] Request timeout: {te}")
        return {"error": "Request timed out", "details": str(te)}
    except requests.exceptions.HTTPError as he:
        print(f"[ERROR] HTTP error: {he}")
        return {"error": f"API returned status code {response.status_code}", "details": response.text}
    except Exception as e:
        print(f"[ERROR] Unexpected error: {e}")
        return {"error": "An unexpected error occurred", "details": str(e)}

