    """
    Load plant configuration from a file.

    Args:
    - file_path (str or Path): Path to the configuration file.

    Returns:
    - dict: Configuration data as a Python dictionary.

    Raises:
    - FileNotFoundError: If the file does not exist.
    - ValueError: If the file is malformed or has an unsupported format.
    """

    # Ensure file_path is a Path object
    file_path = Path(file_path)

    # Check if the file exists
    if not file_path.exists():
        raise FileNotFoundError(f"The file '{file_path}' does not exist.")

    # Detect the file format based on the extension
    if file_path.suffix == '.pickle' or file_path.suffix == '.pkl':
        try:
            with open(file_path, 'rb') as file:
                return pickle.load(file)
        except pickle.UnpicklingError as e:
            raise ValueError(f"Failed to load pickle file: {e}")
    elif file_path.suffix == '.json':
        try:
            with open(file_path, 'r') as file:
                return json.load(file)
        except json.JSONDecodeError as e:
            raise ValueError(f"Failed to parse JSON file: {e}")
    elif file_path.suffix in ['.yaml', '.yml']:
        try:
            with open(file_path, 'r') as file:
                return yaml.safe_load(file)
        except yaml.YAMLError as e:
            raise ValueError(f"Failed to parse YAML file: {e}")
    else:
        raise ValueError(f"Unsupported file format: '{file_path.suffix}'")

# Example usage
if __name__ == "__main__":
    file_path = "config.json"  # Replace with your file path
    try:
        config = load_configuration(file_path)
        print(config)
    except (FileNotFoundError, ValueError) as e:
        print(f"Error: {e}")

import pickle
