import os

def load_plant_configuration(file_path):
    """
    Load plant configuration from a file.

    The function detects the file format based on the extension and returns the configuration as a Python dictionary.
    It supports pickle, JSON, and YAML formats.

    Args:
        file_path (str): The path to the configuration file.

    Returns:
        dict: The plant configuration as a Python dictionary. If the file is missing or malformed, an empty dictionary is returned.
    """

    # Check if the file exists
    if not os.path.exists(file_path):
        print(f"File '{file_path}' not found.")
        return {}

    # Detect the file format based on the extension
    file_extension = os.path.splitext(file_path)[1].lower()

    try:
        # Load configuration based on file format
        if file_extension == '.pickle':
            with open(file_path, 'rb') as file:
                return pickle.load(file)
        elif file_extension == '.json':
            with open(file_path, 'r') as file:
                return json.load(file)
        elif file_extension in ['.yaml', '.yml']:
            with open(file_path, 'r') as file:
                return yaml.safe_load(file)
        else:
            print(f"Unsupported file format: '{file_extension}'")
            return {}
    except Exception as e:
        # Handle any exceptions during file loading
        print(f"Error loading file '{file_path}': {str(e)}")
        return {}

