import os
import pickle
import json
import yaml

def load_plant_config(file_path):
    """
    Load plant configuration from a file in pickle, JSON, or YAML format.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict: A dictionary containing the loaded configuration.

    Raises:
        FileNotFoundError: If the file does not exist.
        ValueError: If the file format is not supported.
        Exception: For other parsing or file reading errors.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Configuration file not found at {file_path}")

    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    try:
        with open(file_path, 'r' if ext in ('.json', '.yaml') else 'rb') as f:
            if ext == '.json':
                return json.load(f)
            elif ext == '.yaml' or ext == '.yml':
                return yaml.safe_load(f)
            elif ext == '.pkl' or ext == '.pickle':
                return pickle.load(f)
            else:
                raise ValueError(f"Unsupported file format: {ext}")
    except Exception as e:
        raise Exception(f"Failed to load configuration from {file_path}: {e}")

import os
import pickle
import json
import yaml

def load_plant_config(file_path):
    """
    Load plant configuration data from a file in pickle, JSON, or YAML format.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict: Parsed configuration data as a dictionary.

    Raises:
        FileNotFoundError: If the file does not exist.
        ValueError: If the file format is unsupported or the content is malformed.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Configuration file not found: {file_path}")

    _, file_ext = os.path.splitext(file_path)
    file_ext = file_ext.lower()

    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            if file_ext == '.json':
                return json.load(f)
            elif file_ext in ('.yaml', '.yml'):
                return yaml.safe_load(f)
            else:
                raise ValueError(f"Unsupported file format: {file_ext}")
    except (json.JSONDecodeError, yaml.YAMLError, pickle.PickleError, UnicodeDecodeError) as e:
        raise ValueError(f"Malformed configuration file: {file_path}") from e
    except Exception as e:
        raise ValueError(f"Unexpected error while reading {file_path}: {e}") from e

import os

def read_document(relative_path):
    """
    Reads and returns the contents of a document given its path relative to the plant documentation base directory.

    Args:
        relative_path (str): Path to the document relative to the base directory.

    Returns:
        str: Contents of the document.

    Raises:
        FileNotFoundError: If the document is not found.
        IsADirectoryError: If the relative path is a directory.
    """
    base_dir = '/var/plant/docs/'
    absolute_path = os.path.join(base_dir, relative_path)

    # Check if the file exists
    if not os.path.exists(absolute_path):
        raise FileNotFoundError(f"Document '{relative_path}' not found.")

    # Check if the path is a file
    if not os.path.isfile(absolute_path):
        if os.path.isdir(absolute_path):
            raise IsADirectoryError(f"'{relative_path}' is a directory.")
        else:
            raise FileNotFoundError(f"'{relative_path}' is not a valid file.")

    try:
        with open(absolute_path, 'r') as file:
            return file.read()
    except Exception as e:
        raise Exception(f"Failed to read document '{relative_path}': {str(e)}")

