from datetime import datetime

def generate_plant_status_dashboard(system_name: str, status_notes: str, log_entries: list = None) -> str:
    """
    Generate HTML for the plant status dashboard.

    Args:
    - system_name (str): The name of the system.
    - status_notes (str): Notes about the system status.
    - log_entries (list, optional): A list of operator log entries. Each entry should be a dictionary with 'timestamp' and 'entry' keys. Defaults to None.

    Returns:
    - str: The HTML string for the plant status dashboard.
    """

    # Start with the basic HTML structure
    html = """
    <html>
    <head>
        <title>Plant Status Dashboard</title>
        <style>
            body {
                font-family: Arial, sans-serif;
            }
            .container {
                max-width: 800px;
                margin: 40px auto;
                padding: 20px;
                background-color: #f9f9f9;
                border: 1px solid #ddd;
                border-radius: 10px;
                box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
            }
            .section {
                margin-bottom: 20px;
            }
            .section h2 {
                margin-top: 0;
            }
            .log-entry {
                margin-bottom: 10px;
                padding: 10px;
                border-bottom: 1px solid #ccc;
            }
            .log-entry:last-child {
                border-bottom: none;
            }
        </style>
    </head>
    <body>
        <div class="container">
    """

    # Add the system information section
    html += """
            <div class="section">
                <h2>System Information</h2>
                <p><strong>System Name:</strong> {system_name}</p>
                <p><strong>Status Notes:</strong> {status_notes}</p>
            </div>
    """.format(system_name=system_name, status_notes=status_notes)

    # Add the operator log entries section
    html += """
            <div class="section">
                <h2>Operator Log Entries</h2>
    """
    if log_entries is None or len(log_entries) == 0:
        html += """
                <p>No log entries available.</p>
        """
    else:
        for entry in log_entries:
            timestamp = entry.get('timestamp', datetime.now().strftime("%Y-%m-%d %H:%M:%S"))
            html += """
                <div class="log-entry">
                    <p><strong>Timestamp:</strong> {timestamp}</p>
                    <p>{entry}</p>
                </div>
            """.format(timestamp=timestamp, entry=entry.get('entry', ''))

    # Close the HTML structure
    html += """
            </div>
        </div>
    </body>
    </html>
    """

    return html

