import requests
from typing import Optional, Dict, Any

def fetch_nrc_data(api_url: str, params: Optional[Dict] = None, timeout: int = 10) -> Dict[str, Any]:
    """
    Fetches data from the NRC API.

    Args:
        api_url (str): The endpoint URL for the NRC API.
        params (Dict, optional): Query parameters for the API request.
        timeout (int): Timeout in seconds for the request.

    Returns:
        Dict: A dictionary containing the response data or error information.
    """
    try:
        response = requests.get(api_url, params=params, timeout=timeout)

        # Raise exception for HTTP errors (4xx, 5xx)
        response.raise_for_status()

        # Attempt to parse JSON
        if 'application/json' in response.headers.get('Content-Type', ''):
            return {'success': True, 'data': response.json()}
        else:
            return {'success': True, 'data': response.text}

    except requests.exceptions.Timeout:
        return {'success': False, 'error': 'Request timed out'}

    except requests.exceptions.ConnectionError:
        return {'success': False, 'error': 'Failed to connect to the API'}

    except requests.exceptions.HTTPError as e:
        return {'success': False, 'error': f'HTTP error: {e.response.status_code} - {e.response.reason}'}

    except requests.exceptions.RequestException as e:
        return {'success': False, 'error': f'Request failed: {str(e)}'}

    except ValueError:
        return {'success': False, 'error': 'Failed to decode JSON response'}

