from datetime import datetime

def search_patients(
    patients, 
    name=None, 
    department=None, 
    start_date=None, 
    end_date=None
):
    """
    Search for patient records based on partial name, department, and last visit date range.

    Parameters:
    - patients (list of dict): List of patient records. Each record should have:
        'name', 'department', 'last_visit'
    - name (str): Partial name to match case-insensitively.
    - department (str): Filter by department.
    - start_date (str or datetime): Start of date range (inclusive).
    - end_date (str or datetime): End of date range (inclusive).

    Returns:
    - List of matching patient dictionaries.
    """

    results = []

    for patient in patients:
        name_match = True
        department_match = True
        date_match = True

        # Partial name match (case-insensitive)
        if name:
            if name.lower() not in patient.get('name', '').lower():
                name_match = False

        # Department filter
        if department:
            if department.lower() != patient.get('department', '').lower():
                department_match = False

        # Last visit date filter
        if start_date or end_date:
            try:
                last_visit = datetime.strptime(patient.get('last_visit', ''), '%Y-%m-%d')
            except (ValueError, TypeError):
                last_visit = None

            if start_date:
                try:
                    start = datetime.strptime(start_date, '%Y-%m-%d')
                except ValueError:
                    start = None
                if start and (last_visit is None or last_visit < start):
                    date_match = False

            if end_date:
                try:
                    end = datetime.strptime(end_date, '%Y-%m-%d')
                except ValueError:
                    end = None
                if end and (last_visit is None or last_visit > end):
                    date_match = False

        if name_match and department_match and date_match:
            results.append(patient)

    return results

