                if start_date:
                    start = datetime.strptime(start_date, "%Y-%m-%d")
                    if last_visit_date < start:
                        matches = False
                if end_date:
                    end = datetime.strptime(end_date, "%Y-%m-%d")
                    if last_visit_date > end:
                        matches = False

        if matches:
            results.append(record)

    return results

