import os
import pickle
import json
import yaml

def load_clinical_config(file_path):
    """
    Load clinical configuration from a file in pickle, JSON, or YAML format.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict or str: The configuration as a dictionary, or an error message if loading fails.
    """
    if not os.path.exists(file_path):
        return f"Error: File not found at {file_path}"

    try:
        ext = os.path.splitext(file_path)[1].lower()
        with open(file_path, 'r' if ext in ('.json', '.yaml', '.yml') else 'rb') as f:
            if ext == '.json':
                config = json.load(f)
            elif ext in ('.yaml', '.yml'):
                config = yaml.safe_load(f)
            elif ext == '.pkl' or ext == '.pickle':
                config = pickle.load(f)
            else:
                return "Error: Unsupported file format. Supported formats: .json, .yaml, .yml, .pkl, .pickle"
        return config
    except json.JSONDecodeError:
        return "Error: Malformed JSON file"
    except yaml.YAMLError:
        return "Error: Malformed YAML file"
    except pickle.PickleError:
        return "Error: Malformed pickle file"
    except Exception as e:
        return f"Error: {str(e)}"

import os
