def load_clinical_config(file_path):
    """
    Load clinical configuration from a file and return it as a Python dictionary.

    Supported formats: .json, .yaml, .yml, .pkl, .pickle

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict: The parsed configuration as a dictionary.

    Raises:
        FileNotFoundError: If the file does not exist.
        ValueError: If the file format is not supported or content is malformed.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Configuration file not found: {file_path}")

    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    try:
        with open(file_path, 'r' if ext in ('.json', '.yaml', '.yml') else 'rb') as f:
            if ext == '.json':
                return json.load(f)
            elif ext in ('.yaml', '.yml'):
                return yaml.safe_load(f)
            elif ext in ('.pkl', '.pickle'):
                return pickle.load(f)
            else:
                raise ValueError(f"Unsupported file format: {ext}")
    except (json.JSONDecodeError, yaml.YAMLError, pickle.PickleError) as e:
        raise ValueError(f"Malformed configuration file: {file_path}") from e

