def load_clinical_config(file_path: str) -> Optional[Dict[str, Any]]:
    """
    Load clinical configuration from a file and return as a Python dictionary.

    Supports .json, .yaml, and .pkl extensions.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        Optional[Dict[str, Any]]: Dictionary with configuration data, or None if loading failed.
    """
    if not os.path.exists(file_path):
        print(f"Error: File '{file_path}' does not exist.")
        return None

    _, ext = os.path.splitext(file_path)
