import pickle
import os


def load_zone_config(file_path):
    """
    Loads and extracts dispatch zone configuration from a serialized data file.

    Parameters:
        file_path (str): Path to the serialized zone configuration file.

    Returns:
        dict: Dictionary containing zone configurations with key-value pairs:
              {
                  'zone_ids': [list of zone IDs],
                  'boundaries': {zone_id: [boundary coordinates]},
                  'assigned_units': {zone_id: [list of unit IDs]},
                  'priority_routing': {zone_id: priority_value},
              }
    """
    config = {
        'zone_ids': [],
        'boundaries': {},
        'assigned_units': {},
        'priority_routing': {}
    }

    if not os.path.exists(file_path):
        print(f"Error: File '{file_path}' not found.")
        return config

    try:
        with open(file_path, 'rb') as f:
            data = pickle.load(f)

        # Example structure assumption: data = {'zones': [{'id': 1, 'boundaries': [...], 'units': [...], 'priority': 3}, ...]}
        if 'zones' in data:
            for zone in data['zones']:
                zone_id = zone.get('id')
                if zone_id is not None:
                    config['zone_ids'].append(zone_id)
                    config['boundaries'][zone_id] = zone.get('boundaries', [])
                    config['assigned_units'][zone_id] = zone.get('units', [])
                    config['priority_routing'][zone_id] = zone.get('priority', 0)
        else:
            print(f"Warning: File '{file_path}' does not contain expected data structure.")

    except Exception as e:
        print(f"Error reading file '{file_path}': {e}")

    return config

