def get_location_coordinates(address: str, api_key: str) -> dict:
    """
    Geocodes an address using the Google Maps Geocoding API.

    Args:
        address (str): The address to geocode (e.g., "123 Main St, City, State").
        api_key (str): Your Google Maps API key.

    Returns:
        dict: A dictionary containing 'latitude', 'longitude', and 'formatted_address'.
              Returns {'error': '...'} if there's an issue.
    """
    base_url = "https://maps.googleapis.com/maps/api/geocode/json"

    # Construct the request URL
    params = {
        "address": address,
        "key": api_key
    }

    try:
        response = requests.get(base_url, params=params)
        response.raise_for_status()  # Raises an error for HTTP errors

        data = response.json()

        if data['status'] == 'OK':
            # Extract the first result
            location = data['results'][0]['geometry']['location']
            formatted_address = data['results'][0]['formatted_address']
            return {
                "latitude": location['lat'],
                "longitude": location['lng'],
                "formatted_address": formatted_address
            }
        else:
