import os
import glob
import subprocess

def manage_historian_data(directory, operation='list', archive_name=None, archive_type='zip'):
    """
    Manage SCADA historian data files in a directory.

    Parameters:
    - directory (str): Path to the directory containing .dat files
    - operation (str): One of 'list', 'count', or 'archive'
    - archive_name (str): Name of the output archive file (optional for 'archive' operation)
    - archive_type (str): One of 'zip' or 'tar.gz' (default is 'zip')

    Returns:
    - For 'list': list of file paths
    - For 'count': string with the total number of files
    - For 'archive': string with the result message
    """
    if not os.path.isdir(directory):
        return f"Error: Directory '{directory}' does not exist."

    files = glob.glob(os.path.join(directory, "*.dat"))
    if not files:
        return "No .dat files found."

    if operation == 'list':
        return files
    elif operation == 'count':
        return f"Total .dat files found: {len(files)}"
    elif operation == 'archive':
        if not archive_name:
            return "Error: Archive name must be provided for archiving."
        if archive_type not in ('zip', 'tar.gz'):
            return f"Error: Unsupported archive type '{archive_type}'. Use 'zip' or 'tar.gz'."

        archive_path = os.path.join(directory, archive_name)
        try:
            if archive_type == 'zip':
                subprocess.run(['zip', '-r', archive_path] + files, check=True, capture_output=True)
            elif archive_type == 'tar.gz':
                subprocess.run(['tar', '-czvf', archive_path] + files, check=True, capture_output=True)
            return f"Successfully created {archive_type} archive: {archive_path}"
        except subprocess.CalledProcessError as e:
            return f"Error creating archive: {str(e)}"
    else:
        return f"Error: Unknown operation '{operation}'. Supported: 'list', 'count', 'archive'"

import pickle
import json
import yaml

def load_grid_configuration(file_path):
    """
    Load grid configuration from a file.

    Supports pickle, JSON, and YAML formats. The format is detected from the file extension.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict or None: The configuration as a Python dictionary, or None if the file is missing or malformed.
    """

    # Check if the file exists
    try:
        with open(file_path, 'rb') as file:
            file_content = file.read()
    except FileNotFoundError:
        print(f"File '{file_path}' not found.")
        return None
    except Exception as e:
        print(f"Error reading file '{file_path}': {str(e)}")
        return None

    # Detect the file format based on the extension
    file_extension = file_path.split('.')[-1].lower()

    # Parse the file content based on the detected format
    if file_extension == 'pickle':
        try:
            return pickle.loads(file_content)
        except pickle.UnpicklingError as e:
            print(f"Error parsing pickle file '{file_path}': {str(e)}")
            return None
    elif file_extension == 'json':
        try:
            return json.loads(file_content.decode('utf-8'))
        except json.JSONDecodeError as e:
            print(f"Error parsing JSON file '{file_path}': {str(e)}")
            return None
    elif file_extension in ['yaml', 'yml']:
        try:
            return yaml.safe_load(file_content.decode('utf-8'))
        except yaml.YAMLError as e:
            print(f"Error parsing YAML file '{file_path}': {str(e)}")
            return None
    else:
        print(f"Unsupported file format '{file_extension}' for file '{file_path}'.")
        return None

