import os
import json
import yaml
import pickle

def load_grid_config(file_path):
    """
    Load grid configuration from a file in pickle, JSON, or YAML format.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict: Parsed configuration data as a dictionary.

    Raises:
        FileNotFoundError: If the file does not exist.
        ValueError: If the file format is unsupported or malformed.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The file {file_path} does not exist.")

    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    try:
        with open(file_path, 'r' if ext in ('.json', '.yaml', '.yml') else 'rb') as f:
            if ext == '.json':
                return json.load(f)
            elif ext in ('.yaml', '.yml'):
                return yaml.safe_load(f)
            elif ext == '.pkl' or ext == '.pickle':
                return pickle.load(f)
            else:
                raise ValueError(f"Unsupported file format: {ext}")
    except (json.JSONDecodeError, yaml.YAMLError, pickle.PickleError, UnicodeDecodeError) as e:
        raise ValueError(f"Malformed file {file_path}: {e}")

