                return json.load(f)
            elif ext == '.yaml' or ext == '.yml':
                return yaml.safe_load(f)
            elif ext == '.pkl' or ext == '.pickle':
                # For pickle, we need to open in binary mode
                with open(file_path, 'rb') as f_bin:
                    return pickle.load(f_bin)
            else:
                raise ValueError(f"Unsupported file format for '{file_path}'. Supported formats: .json, .yaml, .yml, .pkl, .pickle")
    except (json.JSONDecodeError, yaml.YAMLError, pickle.PickleError) as e:
        raise ValueError(f"Malformed configuration file '{file_path}': {e}")

