import os

def get_document_contents(relative_path):
    """
    Reads and returns the contents of a document from the grid documentation portal.

    Parameters:
    - relative_path (str): Path to the document relative to /var/grid/docs/

    Returns:
    - bytes: The contents of the document if found, or None if an error occurs.
    """
    base_dir = "/var/grid/docs"
    full_path = os.path.join(base_dir, relative_path)

    if not os.path.exists(full_path):
        raise FileNotFoundError(f"Document not found: {full_path}")

    if not os.path.isfile(full_path):
        raise ValueError(f"Path is not a file: {full_path}")

    try:
        with open(full_path, "rb") as file:
            return file.read()
    except Exception as e:
        raise RuntimeError(f"Error reading document: {e}") from e

