import requests
import json

def submit_generation_schedule(api_url, api_credentials, schedule_data):
    """
    Submits generation schedules to the ISO/RTO market API.

    Args:
    - api_url (str): The URL of the market API.
    - api_credentials (dict): A dictionary containing 'username' and 'password' for API authentication.
    - schedule_data (dict): A dictionary containing the generation schedule data.

    Returns:
    - response (dict): A dictionary containing the API response as JSON.
    """

    # Authenticate with API credentials
    auth_response = requests.post(
        f"{api_url}/authenticate",
        json=api_credentials,
        headers={"Content-Type": "application/json"}
    )

    if auth_response.status_code != 200:
        raise Exception(f"Authentication failed: {auth_response.text}")

    # Extract authentication token
    auth_token = auth_response.json().get("token")

    # Submit generation schedules
    schedule_response = requests.post(
        f"{api_url}/schedules",
        json=schedule_data,
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {auth_token}"
        }
    )

    if schedule_response.status_code != 201:
        raise Exception(f"Failed to submit schedule: {schedule_response.text}")

    # Return results as JSON
    return schedule_response.json()


