import requests
import json

def fetch_utility_status(utility_url, timeout=5):
    """
    Fetches system status data from a neighboring utility's API.

    Args:
        utility_url (str): The URL of the utility's API endpoint.
        timeout (int, optional): The timeout in seconds for the request. Defaults to 5.

    Returns:
        dict: The JSON response data if successful, or None if an error occurred.
              Returns a dictionary with an 'error' key if a specific error occurred.
    """
    try:
        response = requests.get(utility_url, verify=True, timeout=timeout)  # Verify SSL certificate
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)

        return response.json()

    except requests.exceptions.RequestException as e:
        print(f"Error fetching utility status from {utility_url}: {e}")
        return {"error": str(e)}  # Return error message in a dictionary
    except json.JSONDecodeError as e:
        print(f"Error decoding JSON from {utility_url}: {e}")
        return {"error": "Invalid JSON response"}
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
        return {"error": str(e)}

