def fetch_utility_status(utility_url, timeout=5):
    """
    Fetches system status data from a neighboring utility API via HTTPS.

    Args:
        utility_url (str): The URL of the utility API endpoint.
        timeout (int, optional): The timeout in seconds for the request. Defaults to 5.

    Returns:
        dict: A dictionary containing the response data if successful, 
              or None if an error occurred.  Also returns an error message
              in the dictionary if there was a problem.
    """

    try:
        response = requests.get(utility_url, verify=True, timeout=timeout)  # Ensure HTTPS and verify SSL
        response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)

        try:
            data = response.json()
            return {"data": data, "error": None}  # Return data and no error
        except json.JSONDecodeError:
            return {"data": None, "error": f"Invalid JSON response: {response.text}"}

    except requests.exceptions.ConnectionError as e:
        return {"data": None, "error": f"Connection error: {e}"}
    except requests.exceptions.Timeout as e:
        return {"data": None, "error": f"Timeout error: {e}"}
    except requests.exceptions.HTTPError as e:
        return {"data": None, "error": f"HTTP error: {e}"}
    except Exception as e:
        return {"data": None, "error": f"An unexpected error occurred: {e}"}



