                match = False

        # Filter by contract type
        if contract_type:
            if contract['contract_type'].lower() != contract_type.lower():
                match = False

        # Filter by contract value range
        if min_value is not None:
            if contract['contract_value'] < min_value:
                match = False
        if max_value is not None:
            if contract['contract_value'] > max_value:
                match = False

        if match:
            results.append(contract)

    return results

import subprocess
import glob
import os
import shutil

def manage_tdp_archive(directory, file_pattern='*.tdp'):
    """
    Manage engineering documentation files for defense programs.

    Args:
    - directory (str): The directory to process.
    - file_pattern (str): The file pattern to filter by. Defaults to '*.tdp'.

    Returns:
    - A string or list containing the operation result.
    """

    # Check if the directory exists
    if not os.path.exists(directory):
        return f"Error: Directory '{directory}' does not exist."

    # Get a list of files matching the pattern
    files = glob.glob(os.path.join(directory, file_pattern))

    def list_files():
        """Return a list of matching files."""
        return files

    def count_files():
        """Return the total count of matching files."""
        return len(files)

    def create_archive(archive_name):
        """Create a compressed archive of matching files."""
        # Check if there are any files to archive
        if not files:
            return "No files to archive."

        # Create the archive
        try:
            subprocess.run(['tar', '-czf', archive_name] + files, check=True)
            return f"Archive '{archive_name}' created successfully."
        except subprocess.CalledProcessError as e:
            return f"Error creating archive: {e}"

    # Define the operations
    operations = {
        'list': list_files,
        'count': count_files,
        'archive': create_archive
    }

    # Perform the specified operation
    def perform_operation(operation, archive_name=None):
        if operation in operations:
            if operation == 'archive':
                return operations[operation](archive_name)
            else:
                return operations[operation]()
        else:
            return "Invalid operation."

    return perform_operation

