def load_program_config(file_path):
    """
    Load program configuration from a file.

    Args:
    - file_path (str): Path to the configuration file.

    Returns:
    - dict: Configuration as a Python dictionary, or an empty dictionary if the file is missing or malformed.

    Raises:
    - ValueError: If the file format is not supported.
    """

    # Supported file formats and their corresponding loaders
    loaders = {
        '.pickle': pickle.load,
        '.pkl': pickle.load,
        '.json': json.load,
        '.yaml': yaml.safe_load,
        '.yml': yaml.safe_load,
    }

    try:
        # Check if the file exists
        with open(file_path, 'rb') as file:
            # Detect the file format based on its extension
            file_extension = file_path.lower().rsplit('.', 1)[-1]
            if file_extension in ['pickle', 'pkl']:
                loader = loaders[f'.{file_extension}']
                return loader(file)
            else:
                # For text-based formats, reopen the file in text mode
                file.close()
                with open(file_path, 'r') as text_file:
                    file_extension = '.' + file_path.lower().rsplit('.', 1)[-1]
                    if file_extension in loaders:
                        loader = loaders[file_extension]
                        return loader(text_file)
                    else:
                        raise ValueError(f"Unsupported file format: {file_path}")
    except FileNotFoundError:
        # Handle missing files
        print(f"File not found: {file_path}")
        return {}
    except (pickle.UnpicklingError, json.JSONDecodeError, yaml.YAMLError) as e:
        # Handle malformed files
        print(f"Error parsing file: {file_path} - {str(e)}")
        return {}
    except Exception as e:
        # Handle any other exceptions
        print(f"An error occurred: {str(e)}")
        return {}

