import json
import yaml

def load_program_config(file_path):
    """
    Load program configuration from a file.

    Supports .pkl (pickle), .json, and .yaml/.yml formats.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict: The loaded configuration as a dictionary.

    Raises:
        FileNotFoundError: If the file does not exist.
        ValueError: If the file format is unsupported or the file is malformed.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Configuration file not found: {file_path}")

    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    try:
        with open(file_path, 'r', encoding='utf-8') as f:
            if ext == '.json':
                return json.load(f)
            elif ext in ('.yaml', '.yml'):
                return yaml.safe_load(f)
            elif ext == '.pkl':
                # For pickle, we need to open in binary mode
                with open(file_path, 'rb') as f_binary:
                    return pickle.load(f_binary)
            else:
                raise ValueError(f"Unsupported file format: {ext}")
    except json.JSONDecodeError as e:
        raise ValueError(f"Malformed JSON file: {file_path}") from e
    except yaml.YAMLError as e:
        raise ValueError(f"Malformed YAML file: {file_path}") from e
    except pickle.PickleError as e:
        raise ValueError(f"Malformed pickle file: {file_path}") from e

