def get_contractor_deliverable_status(base_url, api_key, program_id):
    """
    Connects to the contractor API to fetch deliverable status for a given program.

    Parameters:
    - base_url (str): The base URL of the contractor API (e.g., 'https://api.contractor.com/api')
    - api_key (str): The API key for authentication
    - program_id (str): The ID of the program to fetch deliverable status for

    Returns:
    - dict: JSON response from the API containing deliverable status
    """
    # Construct the endpoint URL
    endpoint = f"{base_url}/programs/{program_id}/deliverables/status"

    # Set headers (may vary depending on contractor's API requirements)
    headers = {
        "Accept": "application/json",
        "Authorization": f"Bearer {api_key}"
    }

    try:
        # Send GET request to contractor API
        response = requests.get(endpoint, headers=headers)

        # Check if the request was successful
        if response.status_code == 200:
            return response.json()
        else:
            return {
                "error": "Failed to fetch deliverable status",
                "status_code": response.status_code,
                "response": response.text
            }

    except requests.exceptions.RequestException as e:
        return {
            "error": "API request failed",
            "message": str(e)
        }

import requests
import json

def fetch_program_deliverable_status(api_url, api_key, program_id):
    """
    Connects to a contractor's API, authenticates, fetches program deliverable status,
    and returns the results as JSON.

    Args:
        api_url (str): The base URL of the contractor's API.
        api_key (str): The API key for authentication.
        program_id (str or int): The ID of the program to fetch deliverable status for.

    Returns:
        str: A JSON string representing the program deliverable status.
             Returns None if there's an error during the process.  Includes error messages in the JSON output
             in case of failure.
    """

    try:
        # Construct the full API endpoint URL
        endpoint_url = f"{api_url}/programs/{program_id}/deliverables"  # Example endpoint - adjust as needed

        # Set up headers for authentication
        headers = {
            "Authorization": f"Bearer {api_key}",  # Example authentication - adjust as needed
            "Content-Type": "application/json"  # Important for many APIs
        }

        # Make the API request
        response = requests.get(endpoint_url, headers=headers)

        # Check for successful response (status code 200)
        response.raise_for_status()  # Raises HTTPError for bad responses (4xx or 5xx)

        # Parse the JSON response
        data = response.json()

        # Return the JSON data as a string
        return json.dumps(data, indent=4)  # Indent for readability

    except requests.exceptions.RequestException as e:
        error_message = f"API Request Error: {str(e)}"
        error_data = {"error": error_message}
        return json.dumps(error_data, indent=4)
    except json.JSONDecodeError as e:
        error_message = f"JSON Decode Error: {str(e)}.  Check API Response."
        error_data = {"error": error_message}
        return json.dumps(error_data, indent=4)
    except Exception as e:
        error_message = f"An unexpected error occurred: {str(e)}"
        error_data = {"error": error_message}
        return json.dumps(error_data, indent=4)


