import requests
from requests.exceptions import ConnectionError, Timeout, RequestException

def fetch_parts_availability(supplier_api_url, part_ids, timeout=10):
    """
    Fetches parts availability data from a supplier API.

    Parameters:
    - supplier_api_url (str): The URL of the supplier API endpoint.
    - part_ids (list): List of part IDs to fetch availability for.
    - timeout (int): Request timeout in seconds (default: 10).

    Returns:
    - dict: Parsed JSON response if the request was successful.
    - None: If an error occurred during the request.
    """
    try:
        # Example payload: could vary depending on the API's expected format
        payload = {'part_ids': part_ids}

        # Make the POST request to the supplier API
        response = requests.post(supplier_api_url, json=payload, timeout=timeout)

        # Check for HTTP success status
        if response.status_code == 200:
            return response.json()
        else:
            print(f"API request failed with status code {response.status_code}")
            return None

    except ConnectionError:
        print("Failed to connect to the supplier API. Check the URL and network connection.")
    except Timeout:
        print(f"Request to supplier API timed out after {timeout} seconds.")
    except RequestException as e:
        print(f"An error occurred during the request: {e}")
    except ValueError as e:
        print(f"Failed to decode JSON from response: {e}")

    return None

import requests
from typing import Optional, Dict, Any

def fetch_parts_availability(
    supplier_api_url: str,
    part_ids: list,
    headers: Optional[Dict[str, str]] = None,
    timeout: int = 10
) -> Dict[str, Any]:
    """
    Fetches parts availability data from a supplier API.

    Args:
        supplier_api_url (str): The supplier API endpoint to fetch data.
        part_ids (list): A list of part IDs to query.
        headers (dict, optional): HTTP headers for the request.
        timeout (int, optional): Timeout in seconds for the request. Default is 10.

    Returns:
        dict: JSON response from the supplier API if successful.
              Includes error messages if an error occurs.
    """
    if not part_ids:
        return {"error": "No part IDs provided"}

    try:
        # Prepare the request parameters (e.g., sending part IDs as a JSON payload)
        payload = {"part_ids": part_ids}

        # Make the POST request to the supplier API
        response = requests.post(
            supplier_api_url,
            json=payload,
            headers=headers,
            timeout=timeout
        )

        # Raise an error for HTTP status codes 4xx/5xx
        response.raise_for_status()

        # Return the JSON response
        return response.json()

    except requests.exceptions.ConnectionError:
        return {
            "error": "Connection error: Could not connect to the supplier API."
        }

    except requests.exceptions.Timeout:
        return {
            "error": f"Request timed out after {timeout} seconds."
        }

    except requests.exceptions.HTTPError as e:
        return {
            "error": f"HTTP error occurred: {e.response.status_code} - {e.response.reason}"
        }

    except requests.exceptions.RequestException as e:
        return {
            "error": f"An error occurred during the request: {str(e)}"
        }

import subprocess
import os
import glob
import tarfile

def process_files(directory_path, file_pattern, operation):
    # Validate the directory path
    if not os.path.isdir(directory_path):
        return f"Error: Directory '{directory_path}' does not exist."

    # Construct the full search pattern
    search_pattern = os.path.join(directory_path, file_pattern)

    # Find all matching files
    matching_files = glob.glob(search_pattern)

    if not matching_files:
        return f"No files found matching pattern '{file_pattern}' in '{directory_path}'."

    # Perform the requested operation
    if operation == "list":
        return matching_files

    elif operation == "count":
        return f"Found {len(matching_files)} files matching '{file_pattern}' in '{directory_path}'."

    elif operation == "compress":
        # Create a tar.gz archive of the matching files
        archive_name = os.path.join(directory_path, f"archive_{os.path.basename(directory_path)}.tar.gz")

        try:
            with tarfile.open(archive_name, "w:gz") as tar:
                for file in matching_files:
                    tar.add(file, arcname=os.path.basename(file))

            return f"Successfully created archive '{archive_name}' containing {len(matching_files)} files."
        except Exception as e:
            return f"Error creating archive: {str(e)}"

    else:
        return f"Error: Unknown operation '{operation}'. Valid operations are 'list', 'count', or 'compress'."

