        print(f"Warning: Configuration file '{config_file}' not found. Returning empty config.")
        return config

    try:
        with open(config_file, 'rb') as f:
            # Try loading as pickle first (common for Python serialized objects)
            try:
                config = pickle.load(f)
            except pickle.UnpicklingError:
                # If not pickle, try loading as JSON
                f.seek(0)  # Rewind file
                try:
                    config = json.load(f)
                except json.JSONDecodeError:
                    print(f"Warning: Could not deserialize '{config_file}' as pickle or JSON.")
                    return {}

        # Ensure the loaded data is a dictionary
        if not isinstance(config, dict):
            print(f"Warning: Configuration data in '{config_file}' is not a dictionary.")
            return {}

        return config

    except Exception as e:
        print(f"Error loading configuration from '{config_file}': {str(e)}")
        return {}

