    """
    config = {}

    try:
        # Convert to Path object for more robust path handling
        config_path = Path(config_financial_document)

        # Check if file exists first
        if not config_path.exists():
            print(f"Warning: Configuration file not found at {config_path}")
            return config

        # Try to load the serialized data
        with open(config_path, 'rb') as f:
            config = pickle.load(f)

        # Ensure the loaded data is a dictionary
        if not isinstance(config, dict):
            print("Warning: Loaded configuration data is not in dictionary format")
            return {}

        return config

    except pickle.PickleError as e:
        print(f"Error: Failed to deserialize configuration data - {str(e)}")
        return {}
    except PermissionError:
        print(f"Error: Permission denied when trying to read {config_financial_document}")
        return {}
    except Exception as e:
        print(f"Unexpected error loading configuration: {str(e)}")
        return {}

