import requests
import json

def fetch_https_data(url):
    """
    Fetches data from an HTTPS endpoint and returns it as JSON.

    Args:
        url (str): The HTTPS URL to fetch data from.

    Returns:
        dict: The JSON response data as a Python dictionary.

    Raises:
        ValueError: If the URL is not HTTPS or the response is not valid JSON.
        requests.exceptions.RequestException: For connection-related errors.
    """
    try:
        # Validate URL is HTTPS
        if not url.startswith('https://'):
            raise ValueError("URL must use HTTPS protocol")

        # Make the GET request
        response = requests.get(url, timeout=10)

        # Check for HTTP errors
        response.raise_for_status()

        # Parse and return JSON response
        return response.json()

    except requests.exceptions.SSLError as e:
        raise requests.exceptions.RequestException(f"SSL certificate verification failed: {e}")
    except requests.exceptions.ConnectionError as e:
        raise requests.exceptions.RequestException(f"Connection failed: {e}")
    except requests.exceptions.Timeout as e:
        raise requests.exceptions.RequestException(f"Request timed out: {e}")
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.RequestException(f"HTTP error occurred: {e}")
    except json.JSONDecodeError as e:
        raise ValueError(f"Response is not valid JSON: {e}")
    except Exception as e:
        raise requests.exceptions.RequestException(f"An unexpected error occurred: {e}")

# Example usage
