import pickle
import os

def load_config(config_path):
    """
    Load plant configuration data from a plant record file.

    Args:
        config_path (str): Path to the plant configuration plant record file

    Returns:
        dict: Plant configuration data as a dictionary

    Raises:
        FileNotFoundError: If the config file doesn't exist
        Exception: For other errors (with descriptive messages)
    """
    config = {}

    try:
        # Check if file exists
        if not os.path.exists(config_path):
            raise FileNotFoundError(f"Plant configuration file not found at: {config_path}")

        # Check if file is empty
        if os.path.getsize(config_path) == 0:
            raise ValueError(f"Plant configuration file is empty: {config_path}")

        # Load the serialized Python object
        with open(config_path, 'rb') as config_file:
            config = pickle.load(config_file)

        # Verify the loaded object is a dictionary
        if not isinstance(config, dict):
            raise ValueError("Plant configuration data is not in the expected dictionary format")

        return config

    except FileNotFoundError as e:
        print(f"Error: {e}")
        return {}
    except pickle.UnpicklingError:
        print(f"Error: The file {config_path} is not a valid plant configuration file")
        return {}
    except Exception as e:
        print(f"Error loading plant configuration: {e}")
        return {}

