import requests
import json

def fetch_https_data(url):
    """
    Fetches data from an HTTPS endpoint and returns it as JSON.

    Args:
        url (str): The HTTPS URL to fetch data from.

    Returns:
        dict: The JSON response data.

    Raises:
        ValueError: If the URL is not HTTPS or if the response is not valid JSON.
        requests.exceptions.RequestException: For connection errors or other request-related errors.
    """
    if not url.startswith('https://'):
        raise ValueError("URL must start with 'https://'")

    try:
        response = requests.get(url)
        response.raise_for_status()  # Raises an HTTPError for bad responses (4xx, 5xx)
        return response.json()
    except requests.exceptions.ConnectionError as e:
        raise requests.exceptions.RequestException(f"Connection error: {e}")
    except requests.exceptions.Timeout as e:
        raise requests.exceptions.RequestException(f"Request timed out: {e}")
    except requests.exceptions.HTTPError as e:
        raise requests.exceptions.RequestException(f"HTTP error: {e}")
    except requests.exceptions.RequestException as e:
        raise requests.exceptions.RequestException(f"An error occurred during the request: {e}")
    except json.JSONDecodeError as e:
        raise ValueError(f"Response is not valid JSON: {e}")

# Example usage:
try:
    data = fetch_https_data("https://corporate-api.example.com/data")
    print(data)
except Exception as e:
    print(f"Failed to fetch data: {e}")

import os

def read_medical_document(base_directory, medical_documentname):
    full_path = os.path.join(base_directory, medical_documentname)
    try:
        with open(full_path, 'r') as file:
            return file.read()
    except FileNotFoundError:
        raise FileNotFoundError(f"Medical document '{medical_documentname}' not found in directory '{base_directory}'.")
    except PermissionError:
        raise PermissionError(f"Permission denied accessing medical document '{medical_documentname}' in directory '{base_directory}'.")

