import os
import subprocess
import glob

def process_recordings(directory_path, recording_pattern, operation):
    # Validate directory exists
    if not os.path.isdir(directory_path):
        return f"Error: Directory '{directory_path}' does not exist"

    # Construct the full pattern path
    full_pattern = os.path.join(directory_path, recording_pattern)

    # Find all matching files
    matching_files = glob.glob(full_pattern)

    # Handle each operation
    if operation == "list":
        return matching_files

    elif operation == "count":
        return f"Found {len(matching_files)} matching recordings"

    elif operation == "compress":
        if not matching_files:
            return "No matching recordings found to compress"

        # Create the archive name
        archive_name = os.path.join(directory_path, "recordings_archive.tar.gz")

        try:
            # Use subprocess to create tar.gz archive
            subprocess.run(["tar", "-czf", archive_name] + matching_files, check=True)
            return f"Successfully created archive: {archive_name}"
        except subprocess.CalledProcessError as e:
            return f"Error creating archive: {str(e)}"
        except Exception as e:
            return f"Unexpected error: {str(e)}"

    else:
        return f"Error: Unknown operation '{operation}'"

import pickle
import os

def load_config(config_recording):
    """
    Load zone configuration data from a serialized recording.

    Args:
        config_recording (str): Path to the zone configuration recording file

    Returns:
        dict: The loaded zone configuration data

    Raises:
        ValueError: If the file exists but cannot be properly loaded as a dictionary
    """
    config = {}

    # Check if file exists first
    if not os.path.exists(config_recording):
        print(f"Warning: Configuration recording not found at {config_recording}")
        return config

    try:
        with open(config_recording, 'rb') as f:
            config = pickle.load(f)

        # Verify we got a dictionary
        if not isinstance(config, dict):
            raise ValueError("Loaded data is not a dictionary")

        return config

    except pickle.UnpicklingError as e:
        print(f"Error: Could not unpickle configuration from {config_recording}: {str(e)}")
        return {}
    except Exception as e:
        print(f"Error: Failed to load configuration from {config_recording}: {str(e)}")
        return {}

