import os

def read_historian_data_file(base_directory: str, historian_filename: str) -> str:
    """
    Read and return the contents of a historian data file from a specified base directory.

    Args:
        base_directory: The base directory where historian data files are stored
        historian_filename: The name of the historian data file to read

    Returns:
        The contents of the historian data file as a string

    Raises:
        FileNotFoundError: If the historian data file doesn't exist
        PermissionError: If there are permission issues accessing the file
        OSError: For other filesystem-related errors
    """
    try:
        # Construct the full path
        full_path = os.path.join(base_directory, historian_filename)

        # Verify the path is within the base directory (security check)
        if not os.path.abspath(full_path).startswith(os.path.abspath(base_directory)):
            raise PermissionError("Access to the specified path is not allowed")

        # Read and return the file contents
        with open(full_path, 'r', encoding='utf-8') as file:
            return file.read()

    except FileNotFoundError:
        raise FileNotFoundError(f"The historian data file '{historian_filename}' was not found in '{base_directory}'")
    except PermissionError:
        raise PermissionError(f"Permission denied when trying to read '{historian_filename}' from '{base_directory}'")
    except UnicodeDecodeError:
        # Try with a different encoding if UTF-8 fails
        try:
            with open(full_path, 'r', encoding='latin-1') as file:
                return file.read()
        except Exception as e:
            raise OSError(f"Could not read file with any encoding: {str(e)}")
    except Exception as e:
        raise OSError(f"An error occurred while reading the historian data file: {str(e)}")

# Example usage:
try:
    content = read_historian_data_file("/var/app/data", "operations report.txt")
    print(content)
except Exception as e:
    print(f"Error: {str(e)}")

import os

def read_historian_data_file(base_directory, filename):
    full_path = os.path.join(base_directory, filename)
    try:
        with open(full_path, 'r') as file:
            return file.read()
    except FileNotFoundError:
        raise FileNotFoundError(f"Historian data file not found: {full_path}")
    except PermissionError:
        raise PermissionError(f"Permission denied accessing historian data file: {full_path}")

