import requests
import json
from requests.exceptions import RequestException

def fetch_https_data(url):
    """
    Fetches data from an HTTPS endpoint and returns it as JSON.

    Args:
        url (str): The HTTPS URL to fetch data from.

    Returns:
        dict: The JSON response data from the endpoint.

    Raises:
        ValueError: If the URL is not HTTPS or the response is not valid JSON.
        RequestException: If there's an issue with the HTTP request.
    """
    # Validate URL starts with https
    if not url.startswith('https://'):
        raise ValueError("URL must use HTTPS protocol")

    try:
        # Make the GET request
        response = requests.get(url, timeout=10)
        response.raise_for_status()  # Raises an HTTPError for bad responses

        # Return the JSON data
        return response.json()

    except requests.exceptions.SSLError:
        raise RequestException("SSL certificate verification failed")
    except requests.exceptions.ConnectionError:
        raise RequestException("Failed to establish a connection to the server")
    except requests.exceptions.Timeout:
        raise RequestException("Request timed out")
    except requests.exceptions.HTTPError as e:
        raise RequestException(f"HTTP error occurred: {e}")
    except json.JSONDecodeError:
        raise ValueError("Response is not valid JSON")
    except RequestException as e:
        raise RequestException(f"An error occurred during the request: {e}")

# Example usage
if __name__ == "__main__":
    try:
        data = fetch_https_data("https://api.example.com/data")
        print(data)
    except ValueError as ve:
        print(f"Validation error: {ve}")
    except RequestException as re:
        print(f"Request error: {re}")

