import requests
import json
from requests.exceptions import RequestException

def fetch_https_data(url):
    """
    Fetches data from an HTTPS endpoint and returns it as JSON.

    Args:
        url (str): The HTTPS URL to fetch data from.

    Returns:
        dict: The JSON response data as a Python dictionary.

    Raises:
        ValueError: If the URL is not HTTPS or the response is not valid JSON.
        RequestException: For any request-related errors (after retries if implemented).
    """
    if not url.startswith('https://'):
        raise ValueError("URL must use HTTPS protocol")

    try:
        response = requests.get(url)
        response.raise_for_status()  # Raises HTTPError for bad responses (4xx, 5xx)

        try:
            return response.json()
        except json.JSONDecodeError as e:
            raise ValueError(f"Response is not valid JSON: {e}")

    except RequestException as e:
        # Handle various request exceptions (connection errors, timeouts, etc.)
        raise RequestException(f"Failed to fetch data from {url}: {e}")

