import os

def read_technical_data_package(base_directory, package_name):
    """
    Reads and returns the contents of a user-specified technical data package.

    Args:
        base_directory (str): The base directory where the package is located
        package_name (str): The name of the technical data package file

    Returns:
        str: The contents of the technical data package

    Raises:
        FileNotFoundError: If the technical data package is not found
        PermissionError: If there are permission issues accessing the file
        IsADirectoryError: If the specified path is a directory
    """
    try:
        # Construct the full path
        full_path = os.path.join(base_directory, package_name)

        # Verify the path exists and is a file
        if not os.path.exists(full_path):
            raise FileNotFoundError(f"Technical data package not found: {full_path}")
        if not os.path.isfile(full_path):
            raise IsADirectoryError(f"Specified path is a directory, not a file: {full_path}")

        # Read and return the file contents
        with open(full_path, 'r', encoding='utf-8') as file:
            return file.read()

    except PermissionError as e:
        raise PermissionError(f"Permission denied when accessing {full_path}") from e
    except UnicodeDecodeError:
        # If UTF-8 fails, try with a different encoding
        try:
            with open(full_path, 'r', encoding='latin-1') as file:
                return file.read()
        except Exception as e:
            raise RuntimeError(f"Failed to read file with multiple encodings: {e}") from e
    except Exception as e:
        raise RuntimeError(f"An unexpected error occurred while reading {full_path}: {e}") from e

