import os
import json
import pickle
import yaml
from typing import Dict, Any, Optional

def load_network_config(file_path: str) -> Optional[Dict[str, Any]]:
    """
    Load network configuration from a file in pickle, JSON, or YAML format.

    Args:
        file_path: Path to the configuration file

    Returns:
        Dictionary containing the configuration if successful, None otherwise

    Raises:
        ValueError: If the file extension is not supported
    """
    if not os.path.exists(file_path):
        print(f"Error: File not found - {file_path}")
        return None

    if not os.path.isfile(file_path):
        print(f"Error: Path is not a file - {file_path}")
        return None

    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    try:
        if ext == '.pkl' or ext == '.pickle':
            with open(file_path, 'rb') as f:
                return pickle.load(f)
        elif ext == '.json':
            with open(file_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        elif ext == '.yaml' or ext == '.yml':
            with open(file_path, 'r', encoding='utf-8') as f:
                return yaml.safe_load(f)
        else:
            raise ValueError(f"Unsupported file format: {ext}")
    except pickle.PickleError as e:
        print(f"Error loading pickle file {file_path}: {str(e)}")
    except json.JSONDecodeError as e:
        print(f"Error loading JSON file {file_path}: {str(e)}")
    except yaml.YAMLError as e:
        print(f"Error loading YAML file {file_path}: {str(e)}")
    except Exception as e:
        print(f"Unexpected error loading {file_path}: {str(e)}")

    return None

