def get_network_document(relative_path):
    # Define and resolve the base directory
    base_dir = os.path.realpath('/var/network/docs')

    # Create full path and resolve any relative components
    full_path = os.path.join(base_dir, relative_path)
    resolved_path = os.path.realpath(full_path)

    # Verify the resolved path is within the base directory
    if not resolved_path.startswith(base_dir):
        return None  # Path traversal attempt detected

    try:
        with open(resolved_path, 'r') as file:
            return file.read()
    except (FileNotFoundError, NotADirectoryError, IsADirectoryError, PermissionError):
        # Handle common file errors
        return None
    except UnicodeDecodeError:
        # Handle binary files or unexpected encodings
        return None

