import requests
import json
from typing import Dict, Any, Optional

def provision_subscriber_service(
    oss_api_url: str,
    auth_credentials: Dict[str, str],
    subscriber_data: Dict[str, Any],
    timeout: int = 30
) -> Dict[str, Any]:
    """
    Provisions a new subscriber service via OSS/BSS API.

    Args:
        oss_api_url (str): Base URL of the OSS/BSS API (e.g., 'https://api.oss.example.com/v1')
        auth_credentials (dict): Authentication credentials in format:
            {
                'username': 'your_username',
                'password': 'your_password',
                'auth_type': 'basic'  # or 'bearer' or 'api_key'
                # Additional fields depending on auth_type:
                # For bearer: 'token': 'your_token'
                # For api_key: 'api_key': 'your_key', 'header_name': 'X-API-Key'
            }
        subscriber_data (dict): Subscriber provisioning data in format required by OSS
        timeout (int): Request timeout in seconds (default: 30)

    Returns:
        dict: JSON response from OSS API with provisioning results

    Raises:
        requests.exceptions.RequestException: For network-related errors
        ValueError: For invalid input data or API errors
    """

    # Validate input parameters
    if not oss_api_url or not isinstance(oss_api_url, str):
        raise ValueError("Invalid OSS API URL provided")

    if not auth_credentials or not isinstance(auth_credentials, dict):
        raise ValueError("Invalid authentication credentials provided")

    if not subscriber_data or not isinstance(subscriber_data, dict):
        raise ValueError("Invalid subscriber data provided")

    # Prepare session with authentication
    session = requests.Session()

    # Configure authentication based on type
    auth_type = auth_credentials.get('auth_type', 'basic').lower()

    if auth_type == 'basic':
        session.auth = (auth_credentials['username'], auth_credentials['password'])
    elif auth_type == 'bearer':
        if 'token' not in auth_credentials:
            raise ValueError("Bearer token not provided in credentials")
        session.headers.update({'Authorization': f"Bearer {auth_credentials['token']}"})
    elif auth_type == 'api_key':
        if 'api_key' not in auth_credentials or 'header_name' not in auth_credentials:
            raise ValueError("API key or header name not provided in credentials")
        session.headers.update({auth_credentials['header_name']: auth_credentials['api_key']})
    else:
        raise ValueError(f"Unsupported authentication type: {auth_type}")

    # Set content type header
    session.headers.update({'Content-Type': 'application/json'})

    try:
        # Make provisioning request
        provisioning_endpoint = f"{oss_api_url.rstrip('/')}/subscribers"
        response = session.post(
            provisioning_endpoint,
            data=json.dumps(subscriber_data),
            timeout=timeout
        )

        # Check for successful response
        response.raise_for_status()

        # Return JSON response
        return response.json()

    except requests.exceptions.HTTPError as http_err:
        # Handle API errors
        error_msg = f"OSS API error: {http_err}"
        try:
            error_details = response.json()
            error_msg += f" Details: {error_details}"
        except ValueError:
            error_msg += f" Response: {response.text}"
        raise ValueError(error_msg)

    except requests.exceptions.RequestException as req_err:
        # Handle network errors
        raise requests.exceptions.RequestException(f"Network error while connecting to OSS: {req_err}")

    except json.JSONDecodeError as json_err:
        raise ValueError(f"Invalid JSON response from OSS: {json_err}")

