import requests
import json

class OSSClient:
    def __init__(self, base_url, client_id, client_secret):
        self.base_url = base_url
        self.client_id = client_id
        self.client_secret = client_secret
        self.token = None

    def authenticate(self):
        """Authenticate with the OSS API and store access token"""
        auth_endpoint = f"{self.base_url}/oauth2/token"
        payload = {
            'client_id': self.client_id,
            'client_secret': self.client_secret,
            'grant_type': 'client_credentials'
        }

        try:
            response = requests.post(auth_endpoint, data=payload, timeout=10)
            response.raise_for_status()
            self.token = response.json().get('access_token')
            return True
        except requests.exceptions.RequestException as e:
            print(f"Authentication failed: {str(e)}")
            return False

    def provision_subscriber(self, subscriber_data):
        """Provision new subscriber services"""
        if not self.token:
            if not self.authenticate():
                return json.dumps({
                    "success": False,
                    "error": "Authentication failed"
                })

        provision_endpoint = f"{self.base_url}/api/v1/provisioning/subscribers"
        headers = {
            'Authorization': f'Bearer {self.token}',
            'Content-Type': 'application/json'
        }

        try:
            response = requests.post(
                provision_endpoint,
                headers=headers,
                json=subscriber_data,
                timeout=15
            )

            # Handle 2xx responses
            if response.status_code // 100 == 2:
                return json.dumps({
                    "success": True,
                    "status_code": response.status_code,
                    "data": response.json()
                })

            # Handle error responses
            return json.dumps({
                "success": False,
                "status_code": response.status_code,
                "error": response.text
            })

        except requests.exceptions.RequestException as e:
            return json.dumps({
                "success": False,
                "error": f"API request failed: {str(e)}"
            })

# Example usage
def provision_subscriber_service(subscriber_data):
    # Initialize client with your OSS credentials
    oss = OSSClient(
        base_url="https://oss-api.example.com",
        client_id="your_client_id",
        client_secret="your_client_secret"
    )

    # Attempt provisioning
    result = oss.provision_subscriber(subscriber_data)
    return json.loads(result)  # Return as Python dict (or leave as JSON string)

