import requests
from requests.exceptions import RequestException, Timeout, ConnectionError
from datetime import datetime
from typing import Dict, Any, Optional, Tuple

def fetch_settlement_data(
    api_url: str,
    start_date: str,
    end_date: str,
    auth_token: Optional[str] = None,
    timeout: int = 30,
    max_retries: int = 3
) -> Tuple[bool, Optional[Dict[str, Any]]]:
    """
    Fetch settlement data from partner carrier API for a given date range.

    Args:
        api_url: The base URL of the carrier exchange API
        start_date: Start date in YYYY-MM-DD format
        end_date: End date in YYYY-MM-DD format
        auth_token: Optional authentication token for the API
        timeout: Request timeout in seconds (default: 30)
        max_retries: Maximum number of retry attempts (default: 3)

    Returns:
        Tuple of (success: bool, response_data: dict or None)
        - success: True if request succeeded, False if failed
        - response_data: Dictionary containing the API response or None if failed
    """
    # Validate date format
    try:
        datetime.strptime(start_date, '%Y-%m-%d')
        datetime.strptime(end_date, '%Y-%m-%d')
    except ValueError:
        return False, {"error": "Invalid date format. Use YYYY-MM-DD"}

    # Prepare request parameters
    params = {
        'start_date': start_date,
        'end_date': end_date
    }

    headers = {}
    if auth_token:
        headers['Authorization'] = f'Bearer {auth_token}'

    # Make the request with retries
    for attempt in range(max_retries):
        try:
            response = requests.get(
                api_url,
                params=params,
                headers=headers,
                timeout=timeout
            )

            # Check for successful response
            if response.status_code == 200:
                try:
                    return True, response.json()
                except ValueError:
                    return False, {"error": "Invalid JSON response from server"}
            else:
                return False, {
                    "error": f"API request failed with status {response.status_code}",
                    "status_code": response.status_code,
                    "response": response.text
                }

        except Timeout:
            if attempt == max_retries - 1:
                return False, {"error": f"Request timed out after {timeout} seconds"}
            continue

        except ConnectionError:
            if attempt == max_retries - 1:
                return False, {"error": "Connection error - could not reach the API server"}
            continue

        except RequestException as e:
            return False, {"error": f"Request failed: {str(e)}"}

    return False, {"error": "Max retries exceeded without successful response"}

