import os
import subprocess
import glob
from typing import Union, List

def manage_financial_documents(
    base_dir: str,
    fiscal_year: str = None,
    file_pattern: str = "*.pdf",
    operation: str = "list",
    archive_name: str = None
) -> Union[str, List[str], int]:
    """
    Manage financial documents for compliance archival and audit retrieval.

    Args:
        base_dir: Base directory where financial documents are stored
        fiscal_year: Fiscal year to process (subdirectory name). If None, processes all years.
        file_pattern: File pattern to match (default: "*.pdf")
        operation: Operation to perform - "list", "count", or "archive"
        archive_name: Name for the compressed archive (required for "archive" operation)

    Returns:
        - For "list": List of matching file paths
        - For "count": Integer count of matching files
        - For "archive": Path to created archive file
        - Error message if operation fails
    """
    try:
        # Validate operation
        if operation not in ["list", "count", "archive"]:
            return f"Invalid operation. Must be 'list', 'count', or 'archive'"

        # Build search path based on fiscal year
        if fiscal_year:
            search_path = os.path.join(base_dir, fiscal_year, file_pattern)
        else:
            search_path = os.path.join(base_dir, "*", file_pattern)

        # Find all matching files
        matching_files = glob.glob(search_path)

        if not matching_files:
            return f"No files found matching pattern {file_pattern} in {base_dir}" + (f"/{fiscal_year}" if fiscal_year else "")

        # Perform requested operation
        if operation == "list":
            # Return sorted list of absolute paths
            return sorted([os.path.abspath(file) for file in matching_files])

        elif operation == "count":
            return len(matching_files)

        elif operation == "archive":
            if not archive_name:
                return "Archive name is required for archive operation"

            # Create archive directory if it doesn't exist
            archive_dir = os.path.join(base_dir, "archives")
            os.makedirs(archive_dir, exist_ok=True)

            # Determine archive path
            if not archive_name.endswith(".zip"):
                archive_name += ".zip"
            archive_path = os.path.join(archive_dir, archive_name)

            # Use subprocess to create zip archive
            try:
                # For Windows
                if os.name == 'nt':
                    subprocess.run(
                        ["powershell", "Compress-Archive", "-Path", *matching_files, "-DestinationPath", archive_path],
                        check=True
                    )
                # For Unix/Linux/Mac
                else:
                    subprocess.run(
                        ["zip", "-r", archive_path] + matching_files,
                        check=True
                    )
                return f"Archive created successfully at: {os.path.abspath(archive_path)}"

            except subprocess.CalledProcessError as e:
                return f"Failed to create archive: {str(e)}"
            except FileNotFoundError:
                return "zip utility not found. Please ensure zip is installed on your system."

    except Exception as e:
        return f"An error occurred: {str(e)}"

import os
import json
import yaml
import pickle
from typing import Dict, Any

def load_account_config(file_path: str) -> Dict[str, Any]:
    """
    Load account configuration from a file (pickle, JSON, or YAML).

    Args:
        file_path: Path to the configuration file

    Returns:
        Dictionary containing the configuration data

    Raises:
        ValueError: If file format is unsupported or file is malformed
        FileNotFoundError: If file doesn't exist
    """
    # Check if file exists
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Configuration file not found: {file_path}")

    # Determine file format from extension
    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    try:
        if ext == '.pkl' or ext == '.pickle':
            with open(file_path, 'rb') as f:
                return pickle.load(f)
        elif ext == '.json':
            with open(file_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        elif ext == '.yaml' or ext == '.yml':
            with open(file_path, 'r', encoding='utf-8') as f:
                return yaml.safe_load(f)
        else:
            raise ValueError(f"Unsupported file format: {ext}. Supported formats: .pkl, .json, .yaml/.yml")
    except (pickle.PickleError, json.JSONDecodeError, yaml.YAMLError) as e:
        raise ValueError(f"Failed to parse {ext} file: {str(e)}")
    except Exception as e:
        raise ValueError(f"Error loading configuration file: {str(e)}")

