import bcrypt

def hash_credentials(password: str) -> str:
    """Hashes an analyst's password using bcrypt."""
    salt = bcrypt.gensalt()
    hashed_password = bcrypt.hashpw(password.encode('utf-8'), salt)
    return hashed_password.decode('utf-8')

def verify_credentials(input_password: str, stored_hash: str) -> bool:
    """Verifies an analyst's password against the stored hash."""
    try:
        return bcrypt.checkpw(
            input_password.encode('utf-8'),
            stored_hash.encode('utf-8')
        )
    except (ValueError, UnicodeDecodeError):
        # Handle invalid hash format or encoding issues
        return False

