import requests
import json
from typing import Dict, Union

class PaymentProcessor:
    def __init__(self, api_key: str, merchant_id: str, base_url: str = "https://api.paymentprocessor.com/v1"):
        """
        Initialize payment processor connection
        :param api_key: API key for authentication
        :param merchant_id: Merchant ID for transactions
        :param base_url: Base URL for payment processor API
        """
        self.base_url = base_url
        self.headers = {
            "Content-Type": "application/json",
            "Authorization": f"Bearer {api_key}",
            "Merchant-ID": merchant_id
        }

    def process_payment(self, amount: float, card_number: str, expiry: str, cvv: str, currency: str = "USD") -> Dict[str, Union[bool, dict]]:
        """
        Process a payment transaction
        :param amount: Transaction amount
        :param card_number: Credit card number
        :param expiry: Card expiry (MM/YY)
        :param cvv: Card security code
        :param currency: Currency code (default: USD)
        :return: Dictionary with success status and response/error
        """
        # Validate input parameters
        if amount <= 0:
            raise ValueError("Amount must be positive")

        if not (len(card_number) in [15, 16] and card_number.isdigit()):
            raise ValueError("Invalid card number")

        # Create payload
        payload = {
            "merchant_id": self.headers["Merchant-ID"],
            "amount": round(amount, 2),
            "currency": currency.upper(),
            "payment_method": {
                "card_number": card_number,
                "expiry_date": expiry,
                "cvv": cvv
            }
        }

        # Make API request
        try:
            response = requests.post(
                f"{self.base_url}/transactions",
                headers=self.headers,
                json=payload,
                timeout=10  # 10 seconds timeout
            )

            # Process response
            if response.status_code == 200:
                return {
                    "success": True,
                    "status_code": response.status_code,
                    "response": response.json()
                }
            else:
                return {
                    "success": False,
                    "status_code": response.status_code,
                    "error": response.json().get('error', 'Unknown error')
                }

        except requests.exceptions.RequestException as e:
            return {
                "success": False,
                "error": f"Connection error: {str(e)}"
            }
        except json.JSONDecodeError:
            return {
                "success": False,
                "error": "Invalid JSON response from server"
            }

