import requests
import json

def process_payment(api_credentials, transaction_data, auth_url, payment_url):
    """
    Process a payment through a payment processor API

    Args:
        api_credentials (dict): Dictionary containing client_id and client_secret
        transaction_data (dict): Payment transaction details
        auth_url (str): Authentication endpoint URL
        payment_url (str): Payment processing endpoint URL

    Returns:
        dict: Payment result in JSON format
    """
    try:
        # Authenticate with the payment processor
        auth_response = requests.post(
            auth_url,
            data={
                'client_id': api_credentials['client_id'],
                'client_secret': api_credentials['client_secret'],
                'grant_type': 'client_credentials'
            },
            timeout=10
        )

        auth_response.raise_for_status()
        access_token = auth_response.json()['access_token']

        # Submit payment transaction with obtained token
        headers = {
            'Authorization': f'Bearer {access_token}',
            'Content-Type': 'application/json'
        }

        payment_response = requests.post(
            payment_url,
            headers=headers,
            data=json.dumps(transaction_data),
            timeout=15
        )

        payment_response.raise_for_status()
        return payment_response.json()

    except requests.exceptions.RequestException as e:
        return {
            'error': 'API Connection Error',
            'details': str(e)
        }
    except KeyError as e:
        return {
            'error': 'Invalid API Response',
            'details': f'Missing expected field: {str(e)}'
        }
    except json.JSONDecodeError as e:
        return {
            'error': 'Invalid JSON Response',
            'details': str(e)
        }

