from typing import Dict, Optional

class PaymentProcessor:
    def __init__(self, base_url: str, client_id: str, client_secret: str):
        self.base_url = base_url
        self.client_id = client_id
        self.client_secret = client_secret
        self.access_token: Optional[str] = None
        self.session = requests.Session()

    def authenticate(self) -> Dict:
        """Authenticate with the payment processor API"""
        auth_endpoint = f"{self.base_url}/oauth/token"
        auth_data = {
            'client_id': self.client_id,
            'client_secret': self.client_secret,
            'grant_type': 'client_credentials'
        }

        try:
            response = self.session.post(
                auth_endpoint,
                data=auth_data,
                headers={'Content-Type': 'application/x-www-form-urlencoded'}
            )
            response.raise_for_status()
            auth_response = response.json()
            self.access_token = auth_response.get('access_token')
            return auth_response
        except requests.exceptions.RequestException as e:
            return {
                'error': 'Authentication failed',
                'details': str(e)
            }

    def submit_payment(self, transaction_data: Dict) -> Dict:
        """Submit a payment transaction to the processor"""
        if not self.access_token:
            auth_result = self.authenticate()
            if 'error' in auth_result:
                return auth_result

        payment_endpoint = f"{self.base_url}/v1/payments"
        headers = {
            'Authorization': f'Bearer {self.access_token}',
            'Content-Type': 'application/json'
        }

        try:
            response = self.session.post(
                payment_endpoint,
                json=transaction_data,
                headers=headers,
                timeout=30
            )
            response.raise_for_status()
            return response.json()
        except requests.exceptions.HTTPError as e:
            return {
                'error': 'Payment processing failed',
                'status_code': e.response.status_code,
                'details': e.response.text
            }
        except requests.exceptions.RequestException as e:
            return {
                'error': 'Connection error',
                'details': str(e)
            }

