import requests
import json
from typing import Dict, Union

class PaymentProcessor:
    def __init__(self, api_base_url: str, api_key: str, api_secret: str):
        """
        Initialize the payment processor connection.

        Args:
            api_base_url (str): Base URL of the payment processor API
            api_key (str): API key for authentication
            api_secret (str): API secret for authentication
        """
        self.api_base_url = api_base_url
        self.api_key = api_key
        self.api_secret = api_secret
        self.session = requests.Session()
        self.session.headers.update({
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'User-Agent': 'BankingSystemIntegration/1.0'
        })

    def authenticate(self) -> bool:
        """
        Authenticate with the payment processor API.

        Returns:
            bool: True if authentication successful, False otherwise
        """
        try:
            auth_url = f"{self.api_base_url}/auth"
            auth_data = {
                'api_key': self.api_key,
                'api_secret': self.api_secret
            }

            response = self.session.post(auth_url, json=auth_data)
            response.raise_for_status()

            # Store the authentication token if the API provides one
            auth_response = response.json()
            if 'token' in auth_response:
                self.session.headers.update({
                    'Authorization': f'Bearer {auth_response["token"]}'
                })

            return True

        except requests.exceptions.RequestException as e:
            print(f"Authentication failed: {str(e)}")
            return False

    def submit_payment(self, transaction_data: Dict) -> Dict[str, Union[bool, str, Dict]]:
        """
        Submit a payment transaction to the payment processor.

        Args:
            transaction_data (dict): Dictionary containing transaction details
                Example: {
                    'amount': 100.50,
                    'currency': 'USD',
                    'card_number': '4111111111111111',
                    'expiry_month': '12',
                    'expiry_year': '2025',
                    'cvv': '123',
                    'customer_name': 'John Doe',
                    'reference_id': 'ORD-12345'
                }

        Returns:
            dict: Response containing success status, message, and transaction details
                Example successful response:
                {
                    'success': True,
                    'message': 'Transaction approved',
                    'transaction_id': 'txn_123456789',
                    'response_code': 'APPROVED',
                    'data': { ... }  # Full response from processor
                }
                Example failed response:
                {
                    'success': False,
                    'message': 'Invalid card number',
                    'error_code': 'INVALID_CARD',
                    'data': { ... }
                }
        """
        if not self.authenticate():
            return {
                'success': False,
                'message': 'Failed to authenticate with payment processor'
            }

        try:
            payment_url = f"{self.api_base_url}/transactions"
            response = self.session.post(payment_url, json=transaction_data)
            response.raise_for_status()

            payment_response = response.json()

            # Standardize the response format
            result = {
                'success': payment_response.get('status') == 'approved' or
                          payment_response.get('response_code') in ['APPROVED', 'SUCCESS'],
                'message': payment_response.get('message', 'Transaction processed'),
                'data': payment_response
            }

            # Add transaction-specific fields if available
            if 'transaction_id' in payment_response:
                result['transaction_id'] = payment_response['transaction_id']
            if 'response_code' in payment_response:
                result['response_code'] = payment_response['response_code']
            if 'error_code' in payment_response:
                result['error_code'] = payment_response['error_code']

            return result

        except requests.exceptions.HTTPError as e:
            return {
                'success': False,
                'message': f'HTTP error occurred: {str(e)}',
                'error_code': 'HTTP_ERROR',
                'data': {'status_code': e.response.status_code}
            }
        except requests.exceptions.RequestException as e:
            return {
                'success': False,
                'message': f'Request failed: {str(e)}',
                'error_code': 'REQUEST_ERROR'
            }
        except json.JSONDecodeError:
            return {
                'success': False,
                'message': 'Invalid response format from payment processor',
                'error_code': 'INVALID_RESPONSE'
            }
        except Exception as e:
            return {
                'success': False,
                'message': f'Unexpected error: {str(e)}',
                'error_code': 'UNKNOWN_ERROR'
            }

