from datetime import datetime
from typing import List, Dict, Optional, Union

def lookup_components(
    search_term: Optional[str] = None,
    component_class: Optional[str] = None,
    inspection_start: Optional[Union[str, datetime]] = None,
    inspection_end: Optional[Union[str, datetime]] = None,
    component_database: List[Dict] = None
) -> List[Dict]:
    """
    Search and filter components from the plant information management system.

    Args:
        search_term: Partial component ID or system name to search for
        component_class: Filter by component class ("safety_related", "non_safety", "quality")
        inspection_start: Start date of last inspection range (YYYY-MM-DD)
        inspection_end: End date of last inspection range (YYYY-MM-DD)
        component_database: List of component dictionaries to search through

    Returns:
        List of matching component dictionaries
    """

    if component_database is None:
        raise ValueError("Component database must be provided")

    # Convert date strings to datetime objects if provided
    if isinstance(inspection_start, str):
        inspection_start = datetime.strptime(inspection_start, "%Y-%m-%d")
    if isinstance(inspection_end, str):
        inspection_end = datetime.strptime(inspection_end, "%Y-%m-%d")

    results = []

    for component in component_database:
        # Skip if component doesn't match search term (if provided)
        if search_term:
            search_match = False
            if 'component_id' in component and search_term.lower() in component['component_id'].lower():
                search_match = True
            if 'system_name' in component and search_term.lower() in component['system_name'].lower():
                search_match = True
            if not search_match:
                continue

        # Skip if component doesn't match class filter (if provided)
        if component_class and component.get('component_class') != component_class:
            continue

        # Skip if component doesn't match inspection date range (if provided)
        if 'last_inspection' in component:
            try:
                last_inspection = datetime.strptime(component['last_inspection'], "%Y-%m-%d")
            except (ValueError, TypeError):
                continue

            if inspection_start and last_inspection < inspection_start:
                continue
            if inspection_end and last_inspection > inspection_end:
                continue

        results.append(component)

    return results

