        if search_term:
            term = search_term.lower()
            if (term not in component['id'].lower() and
                term not in component['system_name'].lower()):
                continue

        # Component class filter
        if component_class and component['class'] != component_class:
            continue

        # Last inspection date filter
        if last_inspection_start or last_inspection_end:
            try:
                inspection_date = datetime.strptime(component['last_inspection_date'], "%Y-%m-%d")
            except (ValueError, TypeError):
                continue

            if last_inspection_start and inspection_date < last_inspection_start:
                continue
            if last_inspection_end and inspection_date > last_inspection_end:
                continue

        # If we got here, the component matches all filters
        filtered_components.append(component)

    return filtered_components

import os
import json
import pickle
import yaml
from typing import Dict, Any, Optional

def load_plant_configuration(file_path: str) -> Optional[Dict[str, Any]]:
    """
    Load plant configuration from a file in supported formats (pickle, JSON, YAML).

    Args:
        file_path: Path to the configuration file

    Returns:
        Dictionary containing the configuration data if successful,
        None if the file is missing or malformed

    Raises:
        ValueError: If the file extension is not supported
    """
    if not os.path.exists(file_path):
        print(f"Warning: Configuration file not found at {file_path}")
        return None

    try:
        _, extension = os.path.splitext(file_path)
        extension = extension.lower()

        with open(file_path, 'rb' if extension == '.pkl' else 'r') as f:
            if extension == '.pkl':
                return pickle.load(f)
            elif extension == '.json':
                return json.load(f)
            elif extension in ('.yaml', '.yml'):
                return yaml.safe_load(f)
            else:
                raise ValueError(f"Unsupported file extension: {extension}")

    except (pickle.PickleError, json.JSONDecodeError, yaml.YAMLError) as e:
        print(f"Error: Failed to parse {file_path}: {str(e)}")
        return None
    except Exception as e:
        print(f"Error: Unexpected error loading {file_path}: {str(e)}")
        return None

