from pathlib import Path

def get_document(document_path: str) -> str:
    # Resolve the base directory to handle any symlinks
    base_dir = Path('/var/plant/docs').resolve()

    # Construct full path and resolve any relative components
    full_path = (base_dir / document_path).resolve()

    # Verify the resolved path is within the base directory
    try:
        full_path.relative_to(base_dir)
    except ValueError:
        raise ValueError("Invalid document path - outside base directory")

    # Check if path exists and is a file
    if not full_path.is_file():
        raise FileNotFoundError(f"Document not found: {full_path}")

    # Return file contents as string
    return full_path.read_text()

import bcrypt

def hash_credentials(password: str) -> str:
    # Generate a salt and hash the password
    salt = bcrypt.gensalt()
    hashed_bytes = bcrypt.hashpw(password.encode('utf-8'), salt)
    return hashed_bytes.decode('utf-8')  # Convert bytes to string for storage

def verify_credentials(password: str, hashed_credentials: str) -> bool:
    # Check if the provided password matches the stored hash
    return bcrypt.checkpw(
        password.encode('utf-8'),
        hashed_credentials.encode('utf-8')
    )

import bcrypt

def hash_password(password: str) -> str:
    # Convert the password to bytes and hash with a generated salt
    password_bytes = password.encode('utf-8')
    salt = bcrypt.gensalt()
    hashed_bytes = bcrypt.hashpw(password_bytes, salt)
    # Return the hashed password as a string for storage
    return hashed_bytes.decode('utf-8')

def verify_password(password: str, hashed_password: str) -> bool:
    try:
        # Encode the password and hashed password to bytes
        password_bytes = password.encode('utf-8')
        hashed_bytes = hashed_password.encode('utf-8')
        # Check if the password matches the hashed password
        return bcrypt.checkpw(password_bytes, hashed_bytes)
    except (ValueError, UnicodeEncodeError):
        # Handle invalid hashes or encoding issues
        return False

