import requests
import json

def submit_plant_performance(api_base_url, auth_endpoint, data_endpoint,
                            client_id, client_secret, performance_data):
    """
    Submits plant performance data to corporate systems via API

    Args:
        api_base_url (str): Base URL of the corporate API
        auth_endpoint (str): Authentication endpoint path
        data_endpoint (str): Plant data submission endpoint path
        client_id (str): API client ID
        client_secret (str): API client secret
        performance_data (dict): Plant performance data to submit

    Returns:
        dict: JSON response from corporate system
    """

    # Authenticate and get token
    auth_url = f"{api_base_url}{auth_endpoint}"
    auth_payload = {
        "client_id": client_id,
        "client_secret": client_secret
    }

    try:
        auth_response = requests.post(
            auth_url,
            data=auth_payload,
            timeout=10
        )
        auth_response.raise_for_status()
        token = auth_response.json().get("access_token")

        if not token:
            return {"error": "Authentication failed: No access token received"}

    except requests.exceptions.RequestException as e:
        return {"error": f"Authentication failed: {str(e)}"}

    # Submit performance data
    data_url = f"{api_base_url}{data_endpoint}"
    headers = {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json"
    }

    try:
        data_response = requests.post(
            data_url,
            headers=headers,
            json=performance_data,
            timeout=10
        )
        data_response.raise_for_status()
        return data_response.json()

    except requests.exceptions.RequestException as e:
        if e.response is not None:
            return {
                "error": f"Data submission failed: {str(e)}",
                "status_code": e.response.status_code,
                "details": e.response.text
            }
        return {"error": f"Data submission failed: {str(e)}"}

