def fetch_nrc_data(endpoint, params=None, timeout=30):
    """
    Fetch regulatory data from NRC API.

    Args:
        endpoint (str): The specific NRC API endpoint (e.g., 'inspections', 'enforcement')
        params (dict, optional): Query parameters for the API request
        timeout (int, optional): Request timeout in seconds. Defaults to 30.

    Returns:
        dict: The JSON response from the API if successful

    Raises:
        ValueError: If the endpoint is invalid or response is not JSON
        ConnectionError: If there's a network connection problem
        Timeout: If the request times out
        RequestException: For other request-related errors
    """
    # Base URL for NRC API (adjust if different)
    base_url = "https://www.nrc.gov/api/"

    # Validate endpoint
    if not endpoint or not isinstance(endpoint, str):
        raise ValueError("Invalid endpoint provided")

    # Set default params if none provided
    if params is None:
        params = {}

    try:
        # Make HTTPS request to NRC API
        response = requests.get(
            url=f"{base_url}{endpoint}",
            params=params,
            timeout=timeout,
            headers={'Accept': 'application/json'}
        )

        # Raise an exception for HTTP errors
        response.raise_for_status()

        # Parse and return JSON response
        try:
            return response.json()
        except json.JSONDecodeError:
            raise ValueError("API did not return valid JSON data")

    except Timeout:
        raise Timeout(f"Request to NRC API timed out after {timeout} seconds")
    except ConnectionError as e:
        raise ConnectionError(f"Failed to connect to NRC API: {str(e)}")
    except RequestException as e:
        raise RequestException(f"Error making request to NRC API: {str(e)}")

