import requests
import json
from requests.exceptions import RequestException, Timeout, ConnectionError
from typing import Dict, Optional, Union

def fetch_nrc_data(
    endpoint: str,
    timeout: int = 30,
    retries: int = 3,
    api_key: Optional[str] = None,
    params: Optional[Dict] = None
) -> Union[Dict, str]:
    """
    Fetch regulatory data from NRC API with error handling and retries.

    Args:
        endpoint: The NRC API endpoint (e.g., 'inspections', 'enforcement')
        timeout: Request timeout in seconds (default: 30)
        retries: Number of retry attempts for failed requests (default: 3)
        api_key: Optional API key for authentication
        params: Optional query parameters for the request

    Returns:
        Dictionary containing the response data if successful,
        error message string if failed

    Raises:
        ValueError: If invalid parameters are provided
    """
    # Validate inputs
    if not endpoint:
        raise ValueError("Endpoint cannot be empty")

    if timeout <= 0:
        raise ValueError("Timeout must be a positive number")

    if retries < 0:
        raise ValueError("Retries must be a non-negative number")

    # Base URL for NRC API (adjust if different)
    base_url = "https://www.nrc.gov/site-help/developer-resources/api/v1/"

    # Construct headers
    headers = {
        "Accept": "application/json",
        "User-Agent": "NRC-Data-Exchange-Client/1.0"
    }

    if api_key:
        headers["Authorization"] = f"Bearer {api_key}"

    # Set up request parameters
    request_params = params or {}
    request_params["format"] = "json"  # Ensure JSON response

    # Prepare the full URL
    url = f"{base_url}{endpoint}"

    # Attempt the request with retries
    for attempt in range(retries + 1):
        try:
            response = requests.get(
                url,
                headers=headers,
                params=request_params,
                timeout=timeout
            )

            # Check for successful response
            if response.status_code == 200:
                try:
                    return response.json()
                except json.JSONDecodeError:
                    return {
                        "error": "Invalid JSON response from server",
                        "status_code": response.status_code,
                        "content": response.text
                    }

            # Handle non-200 responses
            return {
                "error": f"API request failed with status {response.status_code}",
                "status_code": response.status_code,
                "content": response.text
            }

        except Timeout:
            if attempt == retries:
                return {
                    "error": f"Request timed out after {timeout} seconds",
                    "attempts": attempt + 1
                }
            continue

        except ConnectionError:
            if attempt == retries:
                return {
                    "error": "Failed to connect to NRC API",
                    "attempts": attempt + 1
                }
            continue

        except RequestException as e:
            if attempt == retries:
                return {
                    "error": f"Request failed: {str(e)}",
                    "attempts": attempt + 1
                }
            continue

    # This line should theoretically never be reached
    return {"error": "Unexpected error occurred during request processing"}

import os
import json
import pickle
import yaml
from typing import Dict, Any

def load_clinical_config(file_path: str) -> Dict[str, Any]:
    """
    Load clinical configuration from a file (pickle, JSON, or YAML format).

    Args:
        file_path: Path to the configuration file

    Returns:
        Dictionary containing the configuration data

    Raises:
        ValueError: If the file format is not supported or file is malformed
        FileNotFoundError: If the file doesn't exist
    """
    # Check if file exists
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Configuration file not found: {file_path}")

    # Get file extension and determine format
    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    try:
        if ext == '.pkl' or ext == '.pickle':
            with open(file_path, 'rb') as f:
                return pickle.load(f)
        elif ext == '.json':
            with open(file_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        elif ext == '.yaml' or ext == '.yml':
            with open(file_path, 'r', encoding='utf-8') as f:
                return yaml.safe_load(f)
        else:
            raise ValueError(f"Unsupported file format: {ext}. Supported formats: .pkl, .json, .yaml, .yml")
    except (pickle.PickleError, json.JSONDecodeError, yaml.YAMLError) as e:
        raise ValueError(f"Failed to parse {ext} file: {str(e)}")
    except Exception as e:
        raise ValueError(f"Error loading configuration file: {str(e)}")

