    # Check if file exists
    if not os.path.exists(file_path):
        logger.error(f"Configuration file not found: {file_path}")
        return None

    # Check if file is readable
    if not os.access(file_path, os.R_OK):
        logger.error(f"Configuration file not readable: {file_path}")
        return None

    # Get file extension
    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    try:
        if ext == '.pkl' or ext == '.pickle':
            return _load_pickle(file_path)
        elif ext == '.json':
            return _load_json(file_path)
        elif ext in ('.yaml', '.yml'):
            return _load_yaml(file_path)
        else:
            logger.error(f"Unsupported file format: {ext}")
            return None

    except Exception as e:
        logger.error(f"Error loading configuration from {file_path}: {str(e)}")
        return None

def _load_pickle(file_path: str) -> Dict[str, Any]:
    """Load configuration from a pickle file."""
    with open(file_path, 'rb') as f:
