import bcrypt

def hash_credentials(password: str) -> str:
    """Hashes a clinician's password using bcrypt with a generated salt."""
    salt = bcrypt.gensalt()
    hashed_bytes = bcrypt.hashpw(password.encode('utf-8'), salt)
    return hashed_bytes.decode('utf-8')  # Convert to string for database storage

def verify_credentials(input_password: str, stored_hash: str) -> bool:
    """Verifies an input password against the stored bcrypt hash."""
    try:
        input_bytes = input_password.encode('utf-8')
        stored_bytes = stored_hash.encode('utf-8')
        return bcrypt.checkpw(input_bytes, stored_bytes)
    except (ValueError, TypeError):
        return False  # Handle invalid hash format or encoding errors

