def fetch_patient_lab_results(
    patient_id: str,
    lab_api_base_url: str,
    auth_endpoint: str,
    results_endpoint: str,
    client_id: str,
    client_secret: str,
    timeout: int = 30
) -> Union[Dict, str]:
    """
    Fetches lab results for a specific patient from an external laboratory system.

    Args:
        patient_id: The unique identifier for the patient
        lab_api_base_url: Base URL of the lab system API (e.g., 'https://api.labsystem.com')
        auth_endpoint: Authentication endpoint path (e.g., '/oauth/token')
        results_endpoint: Lab results endpoint path (e.g., '/api/v1/results')
        client_id: API client ID for authentication
        client_secret: API client secret for authentication
        timeout: Request timeout in seconds (default: 30)

    Returns:
        Dictionary containing the lab results if successful, error message if failed
    """

    # Step 1: Authenticate with the lab system API
    try:
        auth_url = f"{lab_api_base_url}{auth_endpoint}"
        auth_data = {
            'grant_type': 'client_credentials',
            'client_id': client_id,
            'client_secret': client_secret
        }

        auth_response = requests.post(
            auth_url,
            data=auth_data,
            headers={'Content-Type': 'application/x-www-form-urlencoded'},
            timeout=timeout
        )
        auth_response.raise_for_status()

        access_token = auth_response.json().get('access_token')
        if not access_token:
            return {"error": "Authentication failed - no access token received"}

    except requests.exceptions.RequestException as e:
        return {"error": f"Authentication failed: {str(e)}"}
    except json.JSONDecodeError:
        return {"error": "Invalid authentication response format"}

    # Step 2: Fetch patient lab results
    try:
        results_url = f"{lab_api_base_url}{results_endpoint}"
        headers = {
            'Authorization': f'Bearer {access_token}',
            'Content-Type': 'application/json'
        }
        params = {'patient_id': patient_id}

        results_response = requests.get(
            results_url,
            headers=headers,
            params=params,
            timeout=timeout
        )
        results_response.raise_for_status()

        # Return the JSON response from the lab system
        return results_response.json()

    except requests.exceptions.RequestException as e:
        return {"error": f"Failed to fetch lab results: {str(e)}"}
    except json.JSONDecodeError:
        return {"error": "Invalid lab results response format"}

import requests
import json
from typing import Dict, Optional, Union

def fetch_lab_results(
    patient_id: str,
    api_base_url: str,
    client_id: str,
    client_secret: str,
    timeout: int = 30
) -> Union[Dict, str]:
    """
    Fetches lab results for a given patient from an external laboratory system.

    Args:
        patient_id: The unique identifier for the patient
        api_base_url: Base URL of the lab system API (e.g., 'https://api.labsystem.com/v1')
        client_id: API client ID for authentication
        client_secret: API client secret for authentication
        timeout: Request timeout in seconds (default: 30)

    Returns:
        Dictionary containing lab results if successful, error message if failed
    """

    # Step 1: Authenticate and get access token
    auth_url = f"{api_base_url}/auth/token"
    auth_data = {
        'grant_type': 'client_credentials',
        'client_id': client_id,
        'client_secret': client_secret
    }

    try:
        # Get access token
        auth_response = requests.post(
            auth_url,
            data=auth_data,
            headers={'Content-Type': 'application/x-www-form-urlencoded'},
            timeout=timeout
        )
        auth_response.raise_for_status()
        access_token = auth_response.json().get('access_token')

        if not access_token:
            return {"error": "Authentication failed - no access token received"}

        # Step 2: Fetch lab results for the patient
        results_url = f"{api_base_url}/patients/{patient_id}/lab-results"
        headers = {
            'Authorization': f'Bearer {access_token}',
            'Accept': 'application/json'
        }

        results_response = requests.get(
            results_url,
            headers=headers,
            timeout=timeout
        )
        results_response.raise_for_status()

        # Return the JSON response
        return results_response.json()

    except requests.exceptions.RequestException as e:
        # Handle various request exceptions
        error_type = type(e).__name__
        if isinstance(e, requests.exceptions.HTTPError):
            try:
                error_details = e.response.json()
            except ValueError:
                error_details = e.response.text
            return {
                "error": f"HTTP Error: {e.response.status_code}",
                "details": error_details
            }
        elif isinstance(e, requests.exceptions.Timeout):
            return {"error": "Request timed out", "details": str(e)}
        elif isinstance(e, requests.exceptions.ConnectionError):
            return {"error": "Connection failed", "details": str(e)}
        else:
            return {"error": error_type, "details": str(e)}
    except Exception as e:
        return {"error": "Unexpected error", "details": str(e)}

import requests
import json
from typing import Dict, Optional, Union

def fetch_patient_lab_results(
    patient_id: str,
    lab_api_base_url: str,
    api_key: str,
    api_secret: str,
    timeout: int = 30,
    additional_params: Optional[Dict] = None
) -> Union[Dict, str]:
    """
    Fetch patient lab results from an external laboratory information system.

    Args:
        patient_id: The unique identifier for the patient in the lab system
        lab_api_base_url: Base URL for the lab system API (e.g., 'https://api.labsystem.com/v1')
        api_key: API key for authentication
        api_secret: API secret for authentication
        timeout: Request timeout in seconds (default: 30)
        additional_params: Optional dictionary of additional query parameters

    Returns:
        Dictionary containing lab results if successful, error message if failed

    Example:
        results = fetch_patient_lab_results(
            patient_id="12345",
            lab_api_base_url="https://api.labsystem.com/v1",
            api_key="your_api_key",
            api_secret="your_api_secret"
        )
    """

    # Prepare the endpoint URL
    endpoint = f"{lab_api_base_url.rstrip('/')}/results"

    # Set up authentication headers
    headers = {
        "Authorization": f"Bearer {api_key}:{api_secret}",
        "Accept": "application/json",
        "Content-Type": "application/json"
    }

    # Prepare query parameters
    params = {"patient_id": patient_id}
    if additional_params:
        params.update(additional_params)

    try:
        # Make the API request
        response = requests.get(
            endpoint,
            headers=headers,
            params=params,
            timeout=timeout
        )

        # Check for successful response
        response.raise_for_status()

        # Return the JSON response
        return response.json()

    except requests.exceptions.HTTPError as http_err:
        error_msg = f"HTTP error occurred: {http_err}"
        if response.status_code == 401:
            error_msg += " - Authentication failed. Check your API credentials."
        elif response.status_code == 404:
            error_msg += " - Patient not found or no lab results available."
        return {"error": error_msg}

    except requests.exceptions.ConnectionError:
        return {"error": "Connection error - could not reach the lab system API"}

    except requests.exceptions.Timeout:
        return {"error": f"Request timed out after {timeout} seconds"}

    except requests.exceptions.RequestException as req_err:
        return {"error": f"An error occurred while making the request: {req_err}"}

    except json.JSONDecodeError:
        return {"error": "Invalid JSON response from the lab system"}

    except Exception as e:
        return {"error": f"An unexpected error occurred: {str(e)}"}

