def get_incident_report(base_dir, filename):
    for root, _, files in os.walk(base_dir):
        if filename in files:
            file_path = os.path.join(root, filename)
            try:
                with open(file_path, 'r') as file:
                    return file.read()
            except IOError:
                return None  # Handle read errors if necessary
    return None

