        api_key (str): Your API key for the mapping service
        mapping_service (str): Which mapping service to use ('google', 'mapbox', 'openstreetmap')

    Returns:
        dict: A dictionary containing 'latitude' and 'longitude' keys with the coordinates
              Returns None if the geocoding fails
    """

    if not api_key and mapping_service != 'openstreetmap':
        raise ValueError("API key is required for the selected mapping service")

    base_url = ""
    params = {}

    if mapping_service.lower() == 'google':
        # Google Maps Geocoding API
        base_url = "https://maps.googleapis.com/maps/api/geocode/json"
        params = {
            'address': address,
            'key': api_key
        }

    elif mapping_service.lower() == 'mapbox':
        # Mapbox Geocoding API
        base_url = f"https://api.mapbox.com/geocoding/v5/mapbox.places/{address}.json"
        params = {
            'access_token': api_key,
            'limit': 1
        }

    elif mapping_service.lower() == 'openstreetmap':
        # Nominatim (OpenStreetMap) - no API key required but has usage limits
        base_url = "https://nominatim.openstreetmap.org/search"
        params = {
            'q': address,
            'format': 'json',
            'limit': 1
        }
        headers = {
            'User-Agent': 'YourCADSystem/1.0 (your@email.com)'  # Required by Nominatim
        }

    else:
        raise ValueError(f"Unsupported mapping service: {mapping_service}")

    try:
        # Make the API request
        if mapping_service.lower() == 'openstreetmap':
            response = requests.get(base_url, params=params, headers=headers)
        else:
            response = requests.get(base_url, params=params)

        response.raise_for_status()  # Raises an HTTPError for bad responses

        data = response.json()

        # Parse the response based on the service
        if mapping_service.lower() == 'google':
            if data.get('status') == 'OK' and data.get('results'):
                location = data['results'][0]['geometry']['location']
                return {
                    'latitude': location['lat'],
                    'longitude': location['lng']
                }

        elif mapping_service.lower() == 'mapbox':
            if data.get('features'):
                coordinates = data['features'][0]['center']
                return {
                    'latitude': coordinates[1],
                    'longitude': coordinates[0]
                }

        elif mapping_service.lower() == 'openstreetmap':
            if data:
                location = data[0]
                return {
                    'latitude': float(location['lat']),
                    'longitude': float(location['lon'])
                }

        # If we get here, no valid results were found
        print(f"No results found for address: {address}")
        return None

    except requests.exceptions.RequestException as e:
        print(f"Error connecting to mapping service: {e}")
        return None
    except json.JSONDecodeError as e:
        print(f"Error parsing mapping service response: {e}")
        return None
    except Exception as e:
        print(f"Unexpected error: {e}")
        return None

import requests
import urllib.parse

def get_location_coordinates(address, api_key=None, service='google'):
    """
    Retrieve geocoded coordinates for a given address using a mapping service API.

    Args:
        address (str): The address to geocode (e.g., "123 Main St, City, State")
        api_key (str): API key for the mapping service
        service (str): Which mapping service to use ('google', 'mapbox', 'here', etc.)

    Returns:
        dict: Dictionary containing latitude and longitude, or None if geocoding fails
              Example: {'latitude': 37.7749, 'longitude': -122.4194}

    Raises:
        ValueError: If required parameters are missing or API request fails
    """
    if not address:
        raise ValueError("Address cannot be empty")

    if not api_key:
        raise ValueError("API key is required")

    # Base URLs for different mapping services
    service_endpoints = {
        'google': 'https://maps.googleapis.com/maps/api/geocode/json',
        'mapbox': 'https://api.mapbox.com/geocoding/v5/mapbox.places/',
        'here': 'https://geocode.search.hereapi.com/v1/geocode'
    }

    if service not in service_endpoints:
        raise ValueError(f"Unsupported mapping service. Choose from: {list(service_endpoints.keys())}")

    try:
        if service == 'google':
            # Google Maps Geocoding API
            params = {
                'address': address,
                'key': api_key
            }
            response = requests.get(service_endpoints[service], params=params)
            response.raise_for_status()
            data = response.json()

            if data['status'] != 'OK':
                raise ValueError(f"Geocoding failed: {data.get('error_message', 'Unknown error')}")

            location = data['results'][0]['geometry']['location']
            return {
                'latitude': location['lat'],
                'longitude': location['lng'],
                'formatted_address': data['results'][0]['formatted_address']
            }

        elif service == 'mapbox':
            # Mapbox Geocoding API
            encoded_address = urllib.parse.quote(address)
            url = f"{service_endpoints[service]}{encoded_address}.json"
            params = {
                'access_token': api_key,
                'limit': 1
            }
            response = requests.get(url, params=params)
            response.raise_for_status()
            data = response.json()

            if not data['features']:
                raise ValueError("No results found for the given address")

            coordinates = data['features'][0]['center']
            return {
                'latitude': coordinates[1],
                'longitude': coordinates[0],
                'formatted_address': data['features'][0]['place_name']
            }

        elif service == 'here':
            # HERE Geocoding API
            params = {
                'q': address,
                'apiKey': api_key
            }
            response = requests.get(service_endpoints[service], params=params)
            response.raise_for_status()
            data = response.json()

            if not data['items']:
                raise ValueError("No results found for the given address")

            position = data['items'][0]['position']
            return {
                'latitude': position['lat'],
                'longitude': position['lng'],
                'formatted_address': data['items'][0]['address']['label']
            }

    except requests.exceptions.RequestException as e:
        raise ValueError(f"API request failed: {str(e)}")
    except (KeyError, IndexError) as e:
        raise ValueError(f"Unexpected API response format: {str(e)}")

