import requests
import urllib.parse

def get_location_coordinates(address, api_key=None, base_url="https://api.mappingservice.com/geocode"):
    """
    Retrieve latitude and longitude coordinates for a given address using a mapping service API.

    Args:
        address (str): The address to geocode (e.g., "123 Main St, City, State")
        api_key (str): API key for the mapping service (optional if already configured)
        base_url (str): Base URL for the mapping service API (default is generic)

    Returns:
        dict: Dictionary containing 'latitude' and 'longitude' if successful, or error details

    Example:
        >>> coords = get_location_coordinates("123 Main St, New York, NY")
        >>> print(coords)
        {'latitude': 40.7128, 'longitude': -74.0060, 'formatted_address': '123 Main St, New York, NY'}
    """

    # Prepare the request parameters
    params = {
        'address': address,
        'key': api_key  # Only include if API requires key in params
    }

    # Remove None values (like if no API key is provided)
    params = {k: v for k, v in params.items() if v is not None}

    # URL encode the address parameter
    encoded_params = urllib.parse.urlencode(params)

    # Set up headers (some APIs require specific headers)
    headers = {
        'Accept': 'application/json',
        'User-Agent': 'CAD-System-Integration/1.0'
    }

    try:
        # Make the API request
        response = requests.get(
            f"{base_url}?{encoded_params}",
            headers=headers,
            timeout=10  # 10 second timeout
        )

        # Check if the request was successful
        response.raise_for_status()

        # Parse the JSON response
        data = response.json()

        # Process the response (this varies by API provider)
        if data.get('status') == 'OK' and data.get('results'):
            result = data['results'][0]
            location = result['geometry']['location']

            return {
                'latitude': location['lat'],
                'longitude': location['lng'],
                'formatted_address': result.get('formatted_address'),
                'accuracy': result.get('geometry', {}).get('location_type')
            }
        else:
            return {
                'error': 'Geocoding failed',
                'details': data.get('status'),
                'message': data.get('error_message', 'No results found')
            }

    except requests.exceptions.RequestException as e:
        return {
            'error': 'API request failed',
            'details': str(e)
        }
    except ValueError as e:
        return {
            'error': 'Response parsing failed',
            'details': str(e)
        }

