import secrets
import string

def generate_session_token(length=32):
    if not isinstance(length, int):
        raise TypeError("Length must be an integer")
    if length <= 0:
        raise ValueError("Length must be a positive integer")
    characters = string.ascii_letters + string.digits
    token = ''.join(secrets.choice(characters) for _ in range(length))
    return token

def lookup_assets(asset_db, search_term=None, equipment_type=None, voltage_class=None):
    """
    Search and filter assets in the grid operations management system.

    Args:
        asset_db (list): List of asset dictionaries to search through
        search_term (str, optional): Partial asset tag or substation name to search for
        equipment_type (str, optional): Equipment type filter (e.g., "transformer")
        voltage_class (str/int, optional): Voltage class filter (e.g., "115kV" or 115000)

    Returns:
        list: Filtered list of asset dictionaries matching the criteria
    """
    results = []

    for asset in asset_db:
        # Check search term if provided
        if search_term:
            search_match = False
            # Check asset tag (case-insensitive partial match)
            if 'asset_tag' in asset and search_term.lower() in str(asset['asset_tag']).lower():
                search_match = True
            # Check substation name (case-insensitive partial match)
            if 'substation' in asset and search_term.lower() in asset['substation'].lower():
                search_match = True
            if not search_match:
                continue

        # Check equipment type if provided
        if equipment_type and 'equipment_type' in asset:
            if asset['equipment_type'].lower() != equipment_type.lower():
                continue

        # Check voltage class if provided
        if voltage_class is not None and 'voltage_class' in asset:
            # Handle both string ("115kV") and numeric (115000) voltage formats
            asset_voltage = asset['voltage_class']
            if isinstance(asset_voltage, str) and isinstance(voltage_class, str):
                if asset_voltage.lower() != voltage_class.lower():
                    continue
            elif isinstance(asset_voltage, (int, float)) and isinstance(voltage_class, (int, float)):
                if asset_voltage != voltage_class:
                    continue
            else:
                # Mixed types - try to convert string to numeric or vice versa
                try:
                    asset_volt_num = float(asset_voltage.rstrip('kV')) * 1000 if isinstance(asset_voltage, str) else asset_voltage
                    filter_volt_num = float(voltage_class.rstrip('kV')) * 1000 if isinstance(voltage_class, str) else voltage_class
                    if asset_volt_num != filter_volt_num:
                        continue
                except (ValueError, AttributeError):
                    continue

        # If we got here, the asset matches all criteria
        results.append(asset)

    return results

