def get_status_class(status_notes):
    """Determine the status class based on status notes"""
    status_lower = status_notes.lower()
    if "alarm" in status_lower or "critical" in status_lower or "emergency" in status_lower:
        return "alarm"
    elif "warning" in status_lower or "caution" in status_lower or "attention" in status_lower:
        return "warning"
    else:
        return "normal"

