    if 'inspections' in permit_data:
        if isinstance(permit_data['inspections'], list):
            result['inspections'] = [
                {
                    'date': insp.get('date'),
                    'type': insp.get('type'),
                    'result': insp.get('result'),
                    'inspector': insp.get('inspector'),
                    'notes': insp.get('notes')
                }
                for insp in permit_data['inspections']
            ]
        elif isinstance(permit_data['inspections'], dict):
            # Handle case where inspections might be a dictionary
            result['inspections'] = [{
                'date': permit_data['inspections'].get('date'),
                'type': permit_data['inspections'].get('type'),
                'result': permit_data['inspections'].get('result')
            }]

    return result

import pickle
import json
import os
from typing import Dict, Any

def load_permit_data(file_path: str) -> Dict[str, Any]:
    """
    Load permit data from a serialized export file and extract relevant fields.

    Args:
        file_path: Path to the serialized permit data file

    Returns:
        Dictionary containing extracted permit data with permit IDs as keys

    Raises:
        FileNotFoundError: If the file doesn't exist (handled gracefully)
        ValueError: If the file format is invalid
    """
    permit_data = {}

    try:
        # Check if file exists
        if not os.path.exists(file_path):
            print(f"Warning: File not found at {file_path}")
            return permit_data

        # Determine file type and load accordingly
        with open(file_path, 'rb') as file:
            try:
                # Try pickle first (common for serialized Python objects)
                data = pickle.load(file)
            except pickle.UnpicklingError:
                # If not pickle, try JSON
                file.seek(0)
                try:
                    data = json.load(file)
                except json.JSONDecodeError as e:
                    raise ValueError(f"Unsupported file format in {file_path}") from e

        # Process the data structure (handles both list of permits and dict)
        if isinstance(data, list):
            permits = data
        elif isinstance(data, dict):
            # If top level is a dict, look for permits in common keys
            permits = data.get('permits', data.get('records', data.get('data', [])))
        else:
            raise ValueError("Unexpected data structure in file")

        # Extract relevant fields for each permit
        for permit in permits:
            try:
                permit_id = permit.get('permit_id') or permit.get('id')
                if not permit_id:
                    continue  # Skip if no ID found

                permit_data[str(permit_id)] = {
                    'permit_id': permit_id,
                    'applicant_info': {
                        'name': permit.get('applicant', {}).get('name') or permit.get('applicant_name'),
                        'contact': permit.get('applicant', {}).get('contact') or permit.get('applicant_contact'),
                        'address': permit.get('applicant', {}).get('address') or permit.get('applicant_address')
                    },
                    'status': permit.get('status') or permit.get('current_status'),
                    'application_date': permit.get('application_date') or permit.get('date_submitted'),
                    'approval_date': permit.get('approval_date') or permit.get('date_approved'),
                    'inspection_records': permit.get('inspections', []) or permit.get('inspection_records', [])
                }
            except Exception as e:
                print(f"Warning: Error processing permit record: {e}")
                continue

    except Exception as e:
        print(f"Error loading permit data from {file_path}: {str(e)}")
        return {}

    return permit_data

