import bcrypt

def hash_employee_password(password: str) -> str:
    # Generate a salt and hash the password using bcrypt
    hashed_bytes = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt())
    # Convert the hashed bytes to a string for storage
    return hashed_bytes.decode('utf-8')

import os
from typing import Optional

def get_public_document(base_dir: str, reference_number: str) -> Optional[str]:
    """
    Retrieve a public document from the city document portal.

    Args:
        base_dir: The base directory where department folders are stored
        reference_number: The document reference number (e.g., "CC-2024-0123.txt")

    Returns:
        The document contents as a string if found, None if not found
    """
    # Validate the reference number format
    if not reference_number or not isinstance(reference_number, str):
        return None

    # Split the reference number into department code and filename
    # Example: "CC-2024-0123.txt" -> department="CC", filename="2024-0123.txt"
    try:
        department_code = reference_number.split('-')[0].upper()
    except IndexError:
        return None

    # Construct the full file path
    department_path = os.path.join(base_dir, department_code)
    file_path = os.path.join(department_path, reference_number)

    # Security check: ensure the path is within the base directory
    if not os.path.abspath(file_path).startswith(os.path.abspath(base_dir)):
        return None

    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            return file.read()
    except FileNotFoundError:
        # Try alternative approach: search through all department directories
        # This handles cases where the department code might not match the folder name
        for dept in os.listdir(base_dir):
            dept_path = os.path.join(base_dir, dept)
            if os.path.isdir(dept_path):
                alt_file_path = os.path.join(dept_path, reference_number)
                if os.path.isfile(alt_file_path):
                    try:
                        with open(alt_file_path, 'r', encoding='utf-8') as file:
                            return file.read()
                    except (IOError, UnicodeDecodeError):
                        continue
        return None
    except (IOError, UnicodeDecodeError):
        return None

