import os
import pickle
import json
import yaml
from typing import Dict, Any, Optional

def load_program_config(file_path: str) -> Optional[Dict[str, Any]]:
    """
    Load program configuration from a file, supporting pickle, JSON, and YAML formats.
    Automatically detects format from file extension.

    Args:
        file_path: Path to the configuration file

    Returns:
        Dictionary containing the configuration data, or None if loading fails
    """
    if not os.path.exists(file_path):
        print(f"Error: File not found - {file_path}")
        return None

    try:
        file_ext = os.path.splitext(file_path)[1].lower()

        with open(file_path, 'rb' if file_ext == '.pkl' else 'r') as f:
            if file_ext == '.pkl':
                return pickle.load(f)
            elif file_ext in ('.json', '.jsn'):
                return json.load(f)
            elif file_ext in ('.yaml', '.yml'):
                return yaml.safe_load(f)
            else:
                print(f"Error: Unsupported file format - {file_ext}")
                return None

    except pickle.PickleError as e:
        print(f"Error loading pickle file: {e}")
    except json.JSONDecodeError as e:
        print(f"Error loading JSON file: {e}")
    except yaml.YAMLError as e:
        print(f"Error loading YAML file: {e}")
    except Exception as e:
        print(f"Unexpected error loading file: {e}")

    return None

