                return pickle.load(f)
        elif ext == '.json':
            with open(file_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        elif ext == '.yaml' or ext == '.yml':
            with open(file_path, 'r', encoding='utf-8') as f:
                return yaml.safe_load(f)
        else:
            raise ValueError(f"Unsupported file extension: {ext}")
    except pickle.PickleError as e:
