from typing import Dict, Any

def load_program_config(file_path: str) -> Dict[str, Any]:
    """
    Load program configuration from a file in pickle, JSON, or YAML format.

    Args:
        file_path: Path to the configuration file

    Returns:
        A dictionary containing the configuration data

    Raises:
        ValueError: If the file extension is not supported or file is malformed
        FileNotFoundError: If the file doesn't exist
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"Configuration file not found: {file_path}")

    _, ext = os.path.splitext(file_path)
    ext = ext.lower()

    try:
        if ext == '.pkl' or ext == '.pickle':
            with open(file_path, 'rb') as f:
                return pickle.load(f)
        elif ext == '.json':
            with open(file_path, 'r', encoding='utf-8') as f:
                return json.load(f)
        elif ext == '.yaml' or ext == '.yml':
            with open(file_path, 'r', encoding='utf-8') as f:
                return yaml.safe_load(f)
        else:
            raise ValueError(f"Unsupported file extension: {ext}. "
                           "Supported extensions are: .pkl, .pickle, .json, .yaml, .yml")
    except (pickle.PickleError, json.JSONDecodeError, yaml.YAMLError) as e:
        raise ValueError(f"Failed to parse {ext} file: {file_path}. Error: {str(e)}")
