    headers = {"Content-Type": "application/x-www-form-urlencoded"}

    try:
        # Step 1: Authenticate and get access token
        auth_response = requests.post(
            f"{api_base_url}/{auth_endpoint}",
            data=auth_payload,
            headers=headers,
            timeout=10
        )
        auth_response.raise_for_status()

        access_token = auth_response.json().get("access_token")
        if not access_token:
            return {"error": "Authentication failed: No access token received"}

        # Step 2: Fetch deliverables with obtained token
        deliverables_headers = {
            "Authorization": f"Bearer {access_token}",
            "Accept": "application/json"
        }

        deliverables_response = requests.get(
            f"{api_base_url}/{deliverables_endpoint}",
            headers=deliverables_headers,
            timeout=10
        )
        deliverables_response.raise_for_status()

        return deliverables_response.json()

    except requests.exceptions.HTTPError as e:
        return {"error": f"HTTP error occurred: {str(e)}", "status_code": e.response.status_code}
    except json.JSONDecodeError:
        return {"error": "Invalid JSON response from API"}
    except requests.exceptions.RequestException as e:
        return {"error": f"Request failed: {str(e)}"}

