import requests
import json
from requests.exceptions import RequestException, Timeout, ConnectionError
from typing import Dict, Any, Optional, Union

def fetch_parts_availability(
    supplier_api_url: str,
    headers: Optional[Dict[str, str]] = None,
    params: Optional[Dict[str, Any]] = None,
    timeout: int = 30,
    retry_attempts: int = 3
) -> Union[Dict[str, Any], str]:
    """
    Fetches parts availability data from a supplier API with error handling.

    Args:
        supplier_api_url: The URL of the supplier's API endpoint
        headers: Optional dictionary of HTTP headers
        params: Optional dictionary of query parameters
        timeout: Request timeout in seconds (default: 30)
        retry_attempts: Number of retry attempts for failed requests (default: 3)

    Returns:
        Dictionary containing the response data if successful,
        or error message string if failed.

    Raises:
        ValueError: If the supplier_api_url is invalid
    """
    if not supplier_api_url:
        raise ValueError("Supplier API URL cannot be empty")

    if headers is None:
        headers = {
            'Accept': 'application/json',
            'Content-Type': 'application/json'
        }

    if params is None:
        params = {}

    for attempt in range(retry_attempts):
        try:
            response = requests.get(
                supplier_api_url,
                headers=headers,
                params=params,
                timeout=timeout
            )

            # Check for HTTP errors
            response.raise_for_status()

            # Try to parse JSON response
            try:
                return response.json()
            except json.JSONDecodeError:
                return {"raw_response": response.text}

        except Timeout:
            if attempt == retry_attempts - 1:
                return f"Request timed out after {timeout} seconds (attempt {attempt + 1} of {retry_attempts})"
            continue

        except ConnectionError:
            if attempt == retry_attempts - 1:
                return f"Connection error occurred (attempt {attempt + 1} of {retry_attempts})"
            continue

        except RequestException as e:
            return f"Request failed: {str(e)}"

    return "Max retry attempts reached without successful response"
